          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"88feb1fe-9f3d-5c32-ad6a-f2e38ce9d3fa","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة املدعي بإثبات اإلعسار -عدم مصادقة املدعى عليهم على إعسار املدعي -عدم قبول الشهادة باإلعسار ملخالفتها للواقع -ثبوت حتايل املدعي باإلعسار على املدعى عليهم -صكوك بإدانة مدعي اإلعسار مببالغ كبيرة -صرف النظر عن دعوى إثبات إعسار املدعي وبقائه يف السجن .","document_number":"34290771","case_number":"34210751","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":"الدائرة أنه لم يظهر ما يوجب املالحظة واهلل املوفق ) .وقد همش","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/8","year":"1434","subject":"إعسار -مطالبة املدعي بإثبات اإلعسار -عدم مصادقة املدعى عليهم على إعسار املدعي -عدم قبول الشهادة باإلعسار ملخالفتها للواقع -ثبوت حتايل املدعي باإلعسار على املدعى عليهم -صكوك بإدانة مدعي اإلعسار مببالغ كبيرة -صرف النظر عن دعوى إثبات إعسار املدعي وبقائه يف السجن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/8 :‬هـ‬\n                      ‫ُ‬                 ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34290771 :‬‬\n                         ‫َر ْق ُم الدعوى‪34210751 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34360623‬تاريخه‪1434/11/13 :‬هـ‬\n\n\n      ‫إعســار‪ -‬مطالبــة املدعــي بإثبــات اإلعســار‪ -‬عــدم مصادقــة املدعــى‬\n      ‫عليهــم علــى إعســار املدعــي‪ -‬عــدم قبــول الشــهادة باإلعســار ملخالفتهــا‬\n      ‫للواقــع‪ -‬ثبــوت حتايــل املدعــي باإلعســار علــى املدعــى عليهــم‪ -‬صكــوك‬\n      ‫بإدانــة مدعــي اإلعســار مببالــغ كبيــرة‪ -‬صــرف النظــر عن دعــوى إثبات‬\n                                            ‫إعســار املدعــي وبقائــه يف الســجن ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم (( العهــد قريــب واملــال أكثــر مــن‬\n                                                                      ‫ذلــك))‬\n      ‫‪ .2‬وقولــه صلــى اهلل عليــه وســلم يف حديــث قبيصــة (( فأصابــت مالــه‬\n                                                                    ‫جائحــة ))‬\n          ‫‪ .3‬وقوله صلى اهلل عليه وسلم (( على اليد ما أخذت حتى تؤديه ))‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد غرمائــه املدعــى عليهــم بــأن يف ذمتــه للمدعــى عليهــم‬\n      ‫ا يف نــص القضيــة ومت‬   ‫مبالــغ ماليــه مبوجــب صكــوك مبينــة تفصي ـ ً‬\n      ‫إيداعــه ســجن امللــز بســبب ذلــك مــن تاريــخ ‪1434/4/5‬ه ـ و مــا زال يف‬\n      ‫الســجن وطلــب إثبــات إعســاره يف مواجهــة غرمائــه‪ ،‬وقــرر أن األمــوال‬\n      ‫أعطاهــا لشــخص وال يعلــم أيــن هــو اآلن‪ ،‬أجــاب املدعــى عليهــم الدائنون‬\n‫‪235‬‬\n\f‫بعــدم مصادقتهــم علــى إعســاره وأنــه محتــال علمـ ًا انــه مت القبــض عليــه‬\n‫يف املطــار عندمــا كان يريــد التوجــه إلــى خــارج اململكــة‪ ،‬قــرر ناظــر‬\n‫القضيــة أنــه ظهــر لــه أن املدعــي محتــال علــى املســاهمني وأن دعــاوى‬\n‫اإلعســار لــو أخــذ بهــا ملجــرد الدعــوى ألصبحــت وســيلة ألكل أمــوال‬\n‫النــاس بالباطــل ولألســباب التــي ذكرهــا ناظــر القضيــة ولقولــه صلــى‬\n‫اهلل عليــه وســلم ((العهــد قريــب واملــال أكثــر مــن ذلــك)) و قولــه صلــى‬\n‫اهلل عليــه وســلم يف حديــث قبيصــة (( فأصابــت مالــه جائحــة)) وقولــه‬\n‫صلــى اهلل عليــه وســلم (( علــى اليــد مــا أخــذت حتــى تؤديــه )) فقــد صدر‬\n‫احلكــم بصــرف النظــر عــن إثبــات اإلعســار وأن يبقــى املدعــي بالســجن‬\n‫حلــن ســداد مــا عليــه أو تنــازل الدائنــن عــن حقهــم أو شــموله مبكرمــة‬\n‫ملكيــة‪ ،‬قــرر املدعــي عــدم القناعــة‪ ،‬صــدر قــرار محكمــة االســتئناف‬\n                                                      ‫باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 34210751‬وتاريــخ ‪1434/05/07‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341101216‬وتاريــخ ‪1434/05/05‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق ‪1434/07/02‬ه ـ افتتحــت اجللســة للنظــر يف الدعــوى‬\n‫املقامــة مــن ‪ ........‬مصــري اجلنســية باإلقامــة رقــم ‪ ........‬ولــم يتــم احضــار‬\n‫املدعــي الســجني رغــم طلبــه مبوجــب برنــت طلــب الســجناء املرفــق‬\n‫باملعاملــة ومبوجــب خطابنــا املوجــه لســعادة مديــر ســجن امللــز يف ويف‬\n‫هــذه اجللســة حضــر الدائنــون ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪........‬‬\n\n                                                                                         ‫‪236‬‬\n\f      ‫ســعودي بالســجل املدنــي رقــم ‪ ........‬و‪ .........‬ســعودي بالســجل املدنــي‬\n      ‫رقــم ‪ ........‬و‪ .........‬مصــري اجلنســية مبوجــب اإلقامــة رقــم و‪ .........‬مصري‬\n      ‫اجلنســية مبوجــب اإلقامــة رقــم ‪ ........‬و ‪ ........‬مصــري اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم ‪ ........‬أصالــة عــن نفســه وبوكالته عن زوجته ‪ ........‬مصرية‬\n      ‫اجلنســية باإلقامــة رقــم ‪ ........‬وذلــك مبوجــب صــك الوكالــة الصــادر مــن‬\n      ‫كتابــة العــدل الثانيــة بالريــاض برقــم ‪ .........‬يف ‪1433/06/17‬ه ـ ويف‬\n      ‫هــذه اجللســة حضــر ‪ ........‬مصــري اجلنســية مبوجــب اإلقامــة رقــم ‪........‬‬\n      ‫وبســؤاله عــن ســبب حضــوره قــال لقــد اتصــل علــي والــد الســجني مــن‬\n      ‫الريــاض وطلــب منــي احلضــور يف هــذه اجللســة للشــهادة بــان ابنــه فقيــر‬\n      ‫ومعســر وبعــد حضــوري وجلوســي مــع الدائنــن خــارج القاعــة تبــن لــي‬\n      ‫أن املدعــي أخــذ أمــوال الدائنــن بغيــر حــق بحجــة تشــغيلها يف التجــارة‬\n      ‫ولــم يــف بوعــده جتاههــم وقــد تبــن لــي أن الدائنــن مجموعــة كبيــرة‬\n      ‫وليــس كمــا ذكــر والــده انــه شــخص واحــد وان الديــن يســير بــل‬\n      ‫علــى العكــس مــن ذلــك الدائنيــون كثيــر ولــم يحضــر منهــم يف هــذه‬\n      ‫اجللســة اال القليــل والديــن كبيــر جــدا وانــا ال اشــهد علــى زور وال اشــهد‬\n      ‫ان املدعــي فقيــر ومعســر واهلل علــى مــا أقــول شــهيد ورفعــت اجللســة‬\n                                                                       ‫إلحضــار املدعــي ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافق‪1434/08/07‬هـ افتتحت‬\n      ‫اجللســة وفيهــا حضــر ‪ ........‬مصــري اجلنســية باإلقامــة رقــم ‪ .........‬احلاضــر‬\n      ‫برفقــة اخلفيــر جنــدي أول وادعــى يف مواجهــة احلاضريــن ‪ ........‬ســعودي‬\n      ‫بالســجل املدنــي رقــم ‪ ........‬و ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪........‬‬\n      ‫و‪ ........‬ســعودي بالســجل املدنــي رقــم ‪ ........‬قائــا يف دعــواه عليهمــا لقــد‬\n      ‫كنــت اعمــل يف جتــارة اجلــواالت ومكائــن التصويــر واألحبــار واملالبس‬\n\n\n‫‪237‬‬\n\f‫واملدعــى عليهــم هــؤالء احلاضــرون وغيرهــم يصــل عددهــم الــى تســعة‬\n‫اشــخاص قــد ســاهموا معــي يف هــذه التجــارة وقــد خســرت هــذه التجــارة‬\n‫واســتصدروا علــى احــكام بإرجــاع رأس مــال كل واحــد علــى حــده‬\n‫وقــد عجــزت عــن ارجــاع هــذه االمــوال وأودعــت ســجن امللــز بســبب‬\n‫ذلــك مــن تاريــخ ‪1433/04/05‬ه ـ ومــا زلــت يف الســجن حتــى االن اطلــب‬\n‫اثبــات اعســاري جتــاه دائنــي احلاضريــن هــذه دعــواي ويف هــذه االثنــاء‬\n‫حضــر ســعودي بالســجل املدنــي رقــم بصفتــه وكيــا عــن املدعــي وذلــك‬\n‫مبوجــب صــك الوكالــة الصــادر مــن كاتــب العــدل املكلــف بــوزارة‬\n‫الداخليــة برقــم ‪ .........‬وبســؤال املدعــى عليهــم أجــاب املدعــى عليــه األول‬\n‫بقولــه لقــد حضــر لــدي املدعــي هــذا احلاضــر وأوهمنــي بأنــه يتاجــر يف‬\n‫اجلــواالت وأحضــر لــي كرتــون جــواالت وطلــب منــي املســاهمة معــه‬\n‫فســاهمت معــه مببلــغ مائــة واربعــن الــف ريــال واعطانــي اربــاح شــهر‬\n‫واحــد فقــط ال أذكــر مقــداره ثــم انقطــع ومت القبــض عليــه اثنــاء‬\n‫محاولــة هروبــه يف املطــار واودع الســجن واســتصدرت صــكا مــن هــذه‬\n‫احملكمــة برقــم ‪ 33157665‬يف ‪1433/03/17‬ه ـ يتضمن إلزام املدعى‬\n‫عليــه (مدعــي االعســار يف هــذه اجللســة ) بإرجــاع رأس مالــي البالــغ قــدره‬\n‫مائــة واربعــون الــف ريــال وأنــا ال أصــادق املدعــي علــى دعــوى االعســار‬\n‫حيــث أنــه قــد احتــال علــي وعلــى جميــع املســاهمني هــذه اجابتــي كمــا‬\n‫اجــاب املدعــى عليــه الثانــي بقولــه اننــي كنــت طالبــا لــدى مدعــي‬\n‫االعســار واوهمنــي بانــه يتاجــر يف املالبــس واالت التصويــر وطلــب منــي‬\n‫املســاهمة معــه فســاهمت معــه مببلــغ مائــة الــف ريــال ولــم يعطنــي شــيئا‬\n‫مــن االربــاح وانقطــع عنــي ومت القبــض عليــه اثنــاء محاولــة هروبــه يف‬\n‫املطــار واودع الســجن واســتصدرت صــكا مــن هــذه احملكمــة برقــم‬\n\n\n                                                                                     ‫‪238‬‬\n\f      ‫‪ 33315985‬يف ‪1433/06/25‬ه ـ يتضمــن الــزام املدعــى عليــه (مدعــي‬\n      ‫االعســار يف هــذه اجللســة )بإرجــاع رأس مالــي البالــغ قــدره مائــة الــف‬\n      ‫ريــال وانــا ال اصــادق املدعــي علــى دعــوى االعســار حيــث انــه قــد احتــال‬\n      ‫علــي وعلــى جميــع املســاهمني هــذه اجابتــي كمــا اجــاب املدعــى عليــه‬\n      ‫الثالــث بقولــه اننــي كنــت طالبــا لــدى مدعــي االعســار ويوجــد لــدي‬\n      ‫محــل جــواالت وحضــر لــدي مدعــي االعســار هــذا احلاضــر وطلــب ان‬\n      ‫يشــتغل عنــدي منــدوب مبيعــات واخــذ مــن عنــدي خمســن جــوال نــوع‬\n      ‫‪ ........‬وباعهــا بســعر اقــل مــن ســعر اجلملــة علــى احــد احملــات واســتمر‬\n      ‫علــى هــذا املنــوال يأخــذ منــي بضاعــة ويبيعهــا باألجــل ولــم يســدد قيمــة‬\n      ‫هــذه البضاعــة وبلــغ اجماليهــا تســعة وســبعني الــف ريــال كمــا اخــذ‬\n      ‫منــي قرضــة قدرهــا واحــد وثمانــون الــف ريــال واصبــح اجمالــي املبلــغ‬\n      ‫الــذي بذمتــه لــي مائــة وســتون الــف ريــال ولــم يقــر لــي ســوى بواحــد‬\n      ‫وثمانــن الــف ريــال مبوجــب الصــك الصــادر مــن هــذه احملكمــة برقــم‬\n      ‫‪ 33106096‬يف ‪1433/02/28‬هـ ‪ ،‬وقد طلبت من مدعي االعسار هذا‬\n      ‫احلاضــر ســداد املبلــغ احملكــوم بــه فواعدنــي علــى طريــق ‪.........‬واســتعد‬\n      ‫بتســليمي شــيك مببلــغ اثنــن وثالثــن الــف ريــال فانتظرتــه حســب‬\n      ‫املوعــد فلــم يحضــر فاتصلــت علــى جوالــه فــرد علــي شــخص باكســتاني‬\n      ‫وقــال لــي ‪.........‬يف املطــار فتوجهــت مباشــرة للمطــار فشــاهدت مدعــي‬\n      ‫االعســار هــذا احلاضــر فقــال لــي باللهجــة املصريــة (اهلل ازاي عرفــت اني‬\n      ‫هنــا ) فقلــت لــه حاللــي هــو الــذي جابنــي وطلبــت مــن ضابــط اجلــوازات‬\n      ‫مــازم اول منــع املديــن هــذا احلاضــر مــن الســفر فقــال ال يوجــد لــدي امــر‬\n      ‫بذلــك وهــو قــد قــص (البوردينــق) ويعتبــر يف حكــم خــارج الســعودية‬\n      ‫فاتصلــت علــى اخــي فبلــغ نســيبي فتوجــه مباشــرة لشــرطة ‪ ........‬وبلــغ‬\n\n\n‫‪239‬‬\n\f‫عــن املذكــور انــه اخــذ جــواالت مــن احملــل ولــم يرجعهــا وبذلــك متكنــا‬\n‫مــن القبــض عليــه ومنعــه مــن الســفر خــارج البــاد واثنــاء القبــض عليــه‬\n‫حضــر بعــض الدائنــن وهــم الدكتــور ‪ ........‬مصــري اجلنســية وأنــا ال‬\n‫أصــادق املدعــي علــى دعــوى االعســار حيــث انــه قــد احتــال علــي وعلــى‬\n‫جميــع املســاهمني هــذه اجابتــي واثنــاء مــا كان املدعــى عليــه الثالــث‬\n‫يجيــب عــن الدعــوى قــام وكيــل املدعــي وطلــب اخلــروج مــن القاعــة فتــم‬\n‫رفــض طلبــه اال انــه لــم يســتجب ألمــر احملكمــة وقــام باخلــروج بحضــور‬\n‫وشــهادة احلاضريــن املذكوريــن واملالزمــن القضائيــن الشــيخ والشــيخ‬\n‫ويف هــذه االثنــاء حضــر ‪ ........‬مصــري اجلنســية باإلقامــة رقــم ‪........‬‬\n‫أصالــة عــن نفســه وبوكالتــه عــن زوجتــه بالوكالــة الصادرة مــن كتابة‬\n‫العــدل الثانيــة بالريــاض برقــم ‪ .........‬يف ‪1433/06/17‬ه ـ واجــاب بقولــه‬\n‫لقــد حضــر لــدي مدعــي االعســار هــذا احلاضــر واوهمنــي بانــه يتاجــر يف‬\n‫اجلــواالت ومكائــن التصويــر وطلــب منــي املســاهمة معــه فســاهمت معــه‬\n‫مببلــغ قــدره ثالثمائــة وثالثــة وخمســون الــف ريــال يخصنــي منهــا مائتــان‬\n‫وثالثــة وخمســون الــف ريــال ويخــص زوجتــي ‪.........‬مائــة الــف ريــال وقــد‬\n‫مت القبــض علــى مدعــي االعســار اثنــاء محاولتــه الهــرب خــارج البــاد يف‬\n‫املطــار واســتصدرت صــكا مــن هــذه احملكمــة برقــم ‪ 333243373‬يف‬\n‫‪1433/07/01‬ه ـ يتضمــن الــزام املدعــى عليــه (مدعــي االعســار يف هــذه‬\n‫اجللســة) بدفــع مبلــغ ثالثمائــة وخمســن الــف ريــال علمــا بــأن املدعي هذا‬\n‫احلاضــر اقســم لــي بــاهلل انــه ميلــك عمــارة يف مصــر خمســة ادوار وانــا ال‬\n‫اصادقــه علــى دعــوى االعســار ألنــه احتــال علــي وعلــى جميــع املســاهمني‬\n‫كمــا حضــر يف هــذه اجللســة مصــري اجلنســية مبوجــب رخصــة االقامــة‬\n‫رقــم واجــاب بقولــه اننــي اعمــل مدرســا للحاســب االلــي يف معهــد ‪.........‬‬\n\n\n                                                                                    ‫‪240‬‬\n\f      ‫للتدريــب ومدعــي االعســار هــذا احلاضــر يعمــل مــدرس لغــة اجنليزيــة يف‬\n      ‫معهــد ‪ .........‬للغــات وكال املعهديــن معهــد ‪.........‬ومعهــد ‪.........‬يف مبنــى‬\n      ‫واحــد وانــا ومدعــي االعســار نســكن يف غرفــة واحــدة وقــد اوهمنــي‬\n      ‫انــه يتاجــر يف اجلــواالت والســتائر وطلــب منــي املســاهمة معــه فســاهمت‬\n      ‫معــه مببلــغ عشــرين الــف ريــال ومت القبــض عليــه اثنــاء محاولــة هروبــه‬\n      ‫خــارج البــاد يف املطــار واســتصدرت صــكا مــن احملكمــة اجلزئيــة‬\n      ‫بالريــاض برقــم ‪ 33154206‬يف ‪1433/03/26‬ه ـ يتضمــن الــزام املدعــى‬\n      ‫عليــه ( دعــي االعســار يف هــذه اجللســة ) ‪ ،‬بدفــع مبلــغ عشــرين الــف‬\n      ‫ريــال وانــا ال اصادقــه علــى دعــوى االعســار ألنــه احتــال علــي وعلــى‬\n      ‫جميــع املســاهمني كمــا حضــر يف هــذه اجللســة ‪ ........‬مصــري اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم ‪ ........‬وقــرر بقولــه انــي مدعــي االعســار‬\n      ‫هــذا احلاضــر قــد احتــال علــي واوهمنــي انــه يتاجــر يف اجلــواالت وطلــب‬\n      ‫منــي املســاهمة معــه فســاهمت معــه مببلــغ ثمانــن الــف ريــال وقــد اقمــت‬\n      ‫عليــه دعــوى يف هــذا املبلــغ مازالــت منظــورة يف هــذه احملكمــة ويف هــذه‬\n      ‫االثنــاء حضــر املدعــي وكالــة املذكــور وبعــرض ذلــك علــى مدعــي‬\n      ‫االعســار قــال صحيــح انــه صــدرت علــي الصكــوك املذكــورة وأنــه مت‬\n      ‫القبــض علــي يف املطــار وكنــت انــوي الســفر لزيــارة والــدي حيــث قــد‬\n      ‫مضــى علــي يف الســعودية قرابــة اخلمــس ســنوات فجــرى ســؤال مدعــي‬\n      ‫االعســار ايــن ذهــب باألمــوال الثابتــة بالصكــوك الشــرعية فقــال‬\n      ‫انهــا عنــد الشــخص الــذي اتعامــل معــه ويدعــى ‪ ........‬مينــي اجلنســية وال‬\n      ‫اعلــم ايــن هــو االن اثــر ذلــك قــال املدعــى عليــه ان مدعــي االعســار قــد‬\n      ‫ذكــر هــذا الــكالم اثنــاء صــدور احلكــم اخلــاص بــي جتاهــه واعطانــي‬\n      ‫ارقــام وعناويــن املذكــور وتبــن عــدم صحتهــا فبنــاء علــى مــا تقــدم مــن‬\n\n\n‫‪241‬‬\n\f‫الدعــوى واالجابــة والصكــوك املذكــورة املرفقــة صورهــا باملعاملــة‬\n‫والتــي التــزم فيهــا مدعــي االعســار بســدادها وحيــث لــم يبــن مدعــي‬\n‫االعســار ايــن ذهــب بهــذه االمــوال وحيــث ان مــا دفــع بــه مــن انــه قــام‬\n‫بتســليمها لشــخص يدعــى مينــي اجلنســية ال يخلــي ســبيله ولقولــه صلــى‬\n‫اهلل عليــه وســلم (العهــد قريــب واملــال اكثــر مــن ذلــك ‪ )..‬احلديــث ‪.‬‬\n‫وقولــه صلــى اهلل عليــه وســلم كمــا يف حديــث قبيصــه (فأصابــت مالــه‬\n‫جائحــة ) واجلائحــة هــي هــاك ظاهــر للمــال وهــذا غيــر متحقــق هنــا بــل‬\n‫املتحقــق قيــام مدعــي االعســار بالتحايــل علــى املســاهمني وحيــث ان‬\n‫دعــاوى االعســار لــو اخــذ بهــا ملجــرد الدعــوى ألصبحــت وســيلة ألكل‬\n‫امــوال النــاس بالباطــل وال ميكــن قبــول الشــهادة يف ذلــك ملخالفتهــا‬\n‫للواقــع فمدعــي االعســار عليــه امــوال كثيــره ادعــاؤه بهالكهــا مــن‬\n‫غيــر اثبــات بينــه ســبب لــرد أي شــهادة يف اثبــات اعســاره بــل الــذي ظهــر‬\n‫مــن صكــوك االحــكام ومــا يف اوراق املعاملــة وطريقــة القبــض علــى‬\n‫املدعــى عليــه انــه محتــال ولقولــه صلــى اهلل عليــه وســلم ( علــى اليــد‬\n‫مــا أخــذت حتــى تؤديــه ) ‪ .‬لذلــك كلــه فقــد حكمــت بصــرف النظــر‬\n‫عــن دعــوى املدعــي يف طلــب اثبــات اعســاره جتــاه دائنيــه وحكمــت‬\n‫ببقائــه يف الســجن حلــن ســداد مــا عليــه مــن ديــون او تنــازل الدائنــن عــن‬\n‫حقهــم او شــموله مبكرمــة ملكيــة وبذلــك حكمــت وبعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــى عليهــم قناعتهــم بــه وقــرر مدعــي االعســار‬\n‫عــدم القناعــة وجــرى تزويــده بصــورة مــن صــك احلكــم لتقــدمي الئحتــه‬\n‫االعتراضيــة خــال مــدة اقصاهــا ثالثــون يومــا فالتــزم بذلــك وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                     ‫حــرر يف ‪1434/08/07‬ه ـ‬\n\n\n                                                                                     ‫‪242‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1435/01/02‬ه ـ‬\n      ‫افتتحت اجللسة الساعة ‪ 08 : 15‬هذا وقد عادت املعاملة من محكمة‬\n      ‫االســتئناف بالريــاض برقــم ‪ 342472929‬وتاريــخ ‪1434/12/18‬ه ـ‬\n      ‫املرفــق بهــا قــرار التصديــق الصــادر مــن الدائــرة احلقوقيــة الثانيــة برقــم‬\n      ‫‪ 34360623‬وتاريــخ ‪1434/11/13‬ه ـ ونــص احلاجــة منــه بعــد املقدمــة‬\n      ‫‪ (:‬وبدراســة الصــك وصــورة ضبطــه والالئحــة وأوراق املعاملــة تقــرر‬\n      ‫الدائــرة أنــه لــم يظهــر مــا يوجــب املالحظــة واهلل املوفــق ) ‪.‬وقــد همــش‬\n      ‫مبضمونــه علــى ظهــر الصــك وامــرت بنقــل ذلــك يف ضبطــه وســجله‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وســلم ‪ .‬حــرر يف ‪ 1435/01/02‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم‬\n      ‫‪ 341101216‬وتاريــخ ‪1434/10/28‬ه ـ املرفــق بهــا الصــك الصــادر‬\n      ‫مــن فضيلــة القاضــي الشــيخ‪ .........‬املســجل برقــم ‪ 34290771‬وتاريــخ‬\n      ‫‪1434/08/8‬ه ـ اخلــاص بدعــوى‪ ........‬ضــد‪ ........‬عــدة غرمــاء وبدارســة‬\n      ‫الصــك وصــورة ضبطــه والالئحــة وأوراق املعاملــة تقــرر الدائــرة أنــه لــم‬\n      ‫يظهــر مــا يوجــب املالحظــة‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                                ‫وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪243‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":235,"source_page_end":243,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ed30c08a5aba1ea954a569024be53a7a57389647dd6705d49b476a7f4e3554ec","normalized_text_hash":"5dcbea03dae42fb992a16d3d6e507ed3453f67aa65f8b8ee6b8ae74b47ad245a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p235-34290771"},{"id":"c5c4704d-246a-56c2-b932-76db57b52ad9","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة املدعي إثبات اإلعسار يف مواجهة بيت املال -دعوى اإلعسار يف مواجهة بيت املال ال تسمع إال بعد صدور اإلذن بذلك من املقام السامي -إفادات اجلهات املختصة -عدم مصادقة املدعى عليه (بيت املال) على إعسار املدعي واملطالبة باستبدال الغرامة املالية بالسجن -شهادة الشهود العدول -ثبوت إعسار املدعي وإنظاره حلن ميسرة.","document_number":"34309203","case_number":"34355693","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/29","year":"1434","subject":"إعسار -مطالبة املدعي إثبات اإلعسار يف مواجهة بيت املال -دعوى اإلعسار يف مواجهة بيت املال ال تسمع إال بعد صدور اإلذن بذلك من املقام السامي -إفادات اجلهات املختصة -عدم مصادقة املدعى عليه (بيت املال) على إعسار املدعي واملطالبة باستبدال الغرامة املالية بالسجن -شهادة الشهود العدول -ثبوت إعسار املدعي وإنظاره حلن ميسرة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/29 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34309203 :‬‬\n                    ‫َر ْق ُم الدعوى‪34355693 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34318086‬تاريخه‪1434/9/13 :‬هـ‬\n\n\n ‫إعســار‪ -‬مطالبــة املدعــي إثبــات اإلعســار يف مواجهــة بيــت املــال‪ -‬دعــوى‬\n ‫اإلعســار يف مواجهــة بيــت املــال ال تســمع إال بعــد صــدور اإلذن بذلــك‬\n ‫مــن املقــام الســامي‪ -‬إفــادات اجلهــات املختصــة ‪ -‬عــدم مصادقــة املدعــى‬\n ‫عليــه (بيــت املــال) علــى إعســار املدعــي واملطالبــة باســتبدال الغرامــة‬\n ‫املاليــة بالســجن‪ -‬شــهادة الشــهود العــدول‪ -‬ثبــوت إعســار املدعــي‬\n                                                     ‫وإنظــاره حلــن ميســرة‪.‬‬\n\n\n\n\n                      ‫ان ُذو ُع ْس َر ٍة فَ َن ِظ َر ٌة إلى َم ْي َس َر ٍة } ‪.‬‬\n                                                                            ‫ك َ‬‫قوله تعالى{ َو ِإن َ‬\n\n\n\n\n ‫دعــوى املدعــي ضــد منــدوب بيــت املــال بأنــه ســبق أن حكــم عليــه يف‬\n ‫قضيــة ابتــزاز مببلــغ قــدره ثالثمائــة ألــف ريــال تــودع يف خزينــة الدولــة‬\n ‫و تصــرف يف املصالــح العامــة واكتســب احلكــم القطعيــة وقــد صــدر‬\n ‫عفــو مــن املقــام الســامي عــن مبلــغ خمســن ألــف ريــال وبقــي يف ذمتــه‬\n ‫مبلــغ قــدره مائتــان وخمســون ألــف ريــال وأنــه مكــث يف الســجن مــدة‬\n ‫تزيــد عــن الثــاث ســنوات لعــدم قدرتــه علــى الســداد وأنــه فقيــر ومعســر‬\n ‫وطلــب إثبــات إعســاره‪ ،‬مت إجــراء الــازم حيــال البحــث والتحــري عــن‬\n ‫أمــوال املدعــى عليــه فلــم يظهــر لــه أمــوا ًال ميكــن الســداد منهــا‪ ،‬أجــاب‬\n\n                                                                                                      ‫‪244‬‬\n\f      ‫منــدوب بيــت املــال بعــدم املصادقــة علــى إعســار املدعــي وطالــب يف حــال‬\n      ‫إثبــات اإلعســار اســتبدال عقوبــة الغرامــة بالســجن‪ ،‬أحضــر املدعــي‬\n      ‫بينــة وهــم ثالثــة شــهود علــى صحــة دعــواه ومت تعديلهــم شــرعاً‪ ،‬أثبــت‬\n      ‫ان ُذو ُع ْسـ َـر ٍة‬\n                        ‫ك َ‬‫{و ِإن َ‬\n                                 ‫ناظــر القضيــة لألســباب املرصــودة ولقولــه تعالــى َ‬\n      ‫َف َن ِظـ َـر ٌة إلــى َم ْي َسـ َـرةٍ} إعســار املدعــي وأفهــم املدعــى عليــه بــأن عليــه‬\n      ‫إنظــار املدعــي حتــى يتيســر الســداد‪ ،‬قــرر املدعــى عليــه عــدم القناعــة‪،‬‬\n                 ‫صــدر قــرار محكمــة االســتئناف باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا د‪ .........‬رئيــس احملكمــة‬\n      ‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة يف محافظــة االحســاء املكلــف برقــم ‪ 34355693‬وتاريــخ‬\n      ‫‪ 1434/07/30‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341848287‬وتاريــخ‬\n      ‫‪ 1434/07/30‬ه ـ حضــر ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫ا لقــد ســبق‬   ‫املدنــي رقــم (‪ ).....‬وادعــى ضــد منــدوب بيــت املــال قائ ـ ً‬\n      ‫وأن حكــم علـ ّـي فضيلتكــم يف قضيــة ابتــزاز بتغرميــي مبلــغ ثالثمائــة‬\n      ‫ألــف ريــال تــودع بخزينــة الدولــة وتصــرف باملصالــح العامــة بالقــرار رقــم‬\n      ‫‪ 238‬وتاريــخ ‪1431/7/3‬ه ـ واملصــادق عليــه مــن محكمــة االســتئناف‬\n      ‫بالقــرار رقــم ‪ 73‬وتاريــخ ‪1432/1/9‬ه ـ وقــد شــملني العفــو امللكــي‬\n      ‫بإعفائــي عــن مبلــغ خمســن ألــف ريــال وبقــي مــن تلــك الغرامــة مبلــغ‬\n      ‫مائتــن وخمســن ألــف ريــال وقــد مكثــت يف الســجن مــدة تزيــد عــن‬\n      ‫الثــاث الســنوات بســبب هــذه القضيــة لعــدم قدرتــي علــى ســداد ذلــك‬\n\n‫‪245‬‬\n\f‫املبلــغ إذ أننــي رجــل فقيــر ومعســر لــذا أطلــب إثبــات إعســاري وكــف‬\n‫غرميــي مــن مالزمتــي والتضييــق علـ ّـي هــذه دعــواي كمــا جــرت الكتابة‬\n‫منــا ملديــر ســجن محافظــة األحســاء بخطابنــا رقــم ‪ 34258739‬وتاريــخ‬\n‫‪1434/2/20‬ه ـ للتحــري عــن أمــوال املذكــور فوردنــا خطــاب مديــر‬\n‫الســجني رقــم ‪........‬وتاريــخ ‪1434/3/16‬ه ـ املتضمــن أنــه مت إكمــال‬\n‫الــازم كمــا وردنــا خطــاب مديــر عــام فــرع وزارة التجــارة والصناعــة‬\n‫باألحســاء رقم‪........‬وتاريــخ ‪1434/3/1‬ه ـ املتضمــن أنــه باالســتعالم عــن‬\n‫طريــق احلاســب اآللــي اتضــح أن املذكــور ليــس لديــه ســجالت جتاريــة‬\n‫حتــى تاريخــه كمــا وردنــا خطــاب مديــر جــوازات األحســاء رقــم ‪........‬‬\n‫وتاريــخ ‪1434/3/1‬ه ـ املتضمــن أنــه ال يوجــد لــه مكفولــن كمــا وردنــا‬\n‫خطــاب مديــر فــرع الزراعــة بالهفــوف رقــم ‪........‬وتاريــخ ‪1434/3/4‬ه ـ‬\n‫املتضمــن أنــه مت البحــث يف ســجالت األقســام ذات العالقــة ولــم يعثــر‬\n‫علــى اســم للمذكــور ضمنهــا كمــا وردنــا خطــاب أمــن األحســاء رقــم‬\n‫‪........‬وتاريــخ ‪1434/3/9‬ه ـ املتضمــن بأنــه ال يوجــد للمذكــور تراخيص‬\n‫جتاريــة أو عقــارات مســتأجرة أو مســتحقات ماليــة كمــا ال يوجــد‬\n‫للمذكــور منــح أراضــي حســب إفــادة وحــدة احلاســب باألمانــة كمــا‬\n‫وردنــا خطــاب مديــر مؤسســة النقــد العربــي الســعودي فــرع الدمــام رقــم‬\n‫ال‬\n ‫‪........‬وتاريــخ ‪1434/6/13‬ه ـ املتضمــن أن املؤسســة تلقــت إجابــة ك ً‬\n‫مــن البنــك ‪ ........‬والــذي أفــاد بــأن هنــاك حســاب جــاري باســم املذكــور‬\n‫ورصيــده ‪ 95.92‬ريــال كمــا أفــاد مصــرف ‪ ........‬بــأن هنــاك حســاب‬\n‫راكــد باســم املذكــور ورصيــده صفــر أمــا باقــي البنــوك واملصــارف‬\n‫فقــد أفــادت عــدم وجــود أي حســابات أو أرصــدة تخــص املذكــور‬\n‫وكان حاضــر ًا ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n\n\n                                                                                   ‫‪246‬‬\n\f      ‫‪ ........‬واملكلــف مــن قبــل مديــر مكتــب وزارة املاليــة باألحســاء املكلف‬\n      ‫ا إنــه تبــن لنــا‬  ‫بخطابــه رقــم ‪........‬وتاريــخ ‪1434/7/30‬ه ـ وقــرر قائ ـ ً‬\n      ‫بــأن القضيــة مــن اختصاصنــا وأمــا مــا ذكــره املدعــي مــن أنــه معســر‬\n      ‫فــا نصــادق علــى ذلــك وال نعلــم عــن حالــه أي شــيء ويف حالــة إثبــات‬\n      ‫إعســاره مــن قبــل فضيلتكــم فإننــا نطلــب اســتبدال الغرامــة املاليــة التــي‬\n      ‫عليــه بعقوبــة الســجن وبســؤال املدعــي هــل لديــه بينــة علــى إعســاره قــال‬\n      ‫نعــم وأحضــر املدعــي كل مــن ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم‪ ........‬و ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ........‬و ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ........‬فشــهد‬\n      ‫ا أشــهد بــاهلل العظيــم بأننــي أعــرف هــذا‬     ‫كل واحــد منهــم مبفــرده قائـ ً‬\n      ‫احلاضــر معرفــة تامــة وأنــه رجــل فقيــر ومعســر وال أعلــم أنــه لــه مــا ًال‬\n      ‫ثابتـ ًا أو منقــو ًال ميكــن أن يســدد منــه املبلــغ احملكــوم بــه عليــه أو بعضــه‬\n      ‫وبعــرض تلــك الشــهادة علــى منــدوب بيــت املــال قــال إننــي ال أقــول يف‬\n      ‫الشــهود إال خيــر وال أعلــم عــن حالــة املدعــي أي شــيء كمــا أحضــر‬\n      ‫ال مــن ســعودي اجلنســية مبوجــب الســجل‬         ‫املدعــي لتزكيــة الشــهود ك ً‬\n      ‫املدنــي رقــم ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫ـاءا علــى مــا تقــدم‬   ‫فشــهدا مبعرفتهــم للشــهود وأنهــم ثقــة وعــدول فبنـ ً‬\n      ‫وحيــث أفــادت اجلهــات املختصــة بأنــه لــم يعثــر للمدعــي مــا ميكــن أن‬\n      ‫يســدد منــه أو يرفــع عنــه وصــف الفقــر واإلعســار وحيــث أثبــت املدعــي‬\n      ‫مــا يدعــي بــه مــن إعســار ببينتــه املعدلــة وألن دالئــل احلــال تؤيــد ما ذكره‬\n      ‫املدعــي ولقولــه تعالــى (فــإن كان ذو عســرة فنظــرة إلــى ميســرة) وإنــه‬\n      ‫ـدي عســر ‪........‬‬ ‫ال مصلحــة مــن حجــزه واحلــال مــا ذكــر لــذا فقــد ثبــت لـ ّ‬\n      ‫وعــدم قدرتــه علــى ســداد املبلــغ احملكــوم بــه عليــه وأفهمــت غرميــه‬\n\n\n‫‪247‬‬\n\f‫منــدوب بيــت املــال بــأن عليــه أن ينظــره حتــى يتيســر لــه الســداد وبذلــك‬\n‫حكمــت وبعرضــه قــرر املدعــي قناعتــه بــه أمــا منــدوب بيــت املــال‬\n‫فاعتــرض عليــه وطلــب رفعــه حملكمــة االســتئناف مكتفي ـ ًا مبــا جــاء‬\n‫يف إجابتــه عــن تقــدمي الئحــة اعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/29‬ه ـ‬\n‫احلمد هلل وحده والصالة والســام على رســولنا محمد وآله وصحبه أما‬\n‫بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف محكمة‬\n‫االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة األحســاء املكلــف الشــيخ‪ ........ /‬برقــم‬\n‫‪ 34/888308‬وتاريــخ ‪1434/9/3‬ه ـ واملقيــدة لــدى احملكمــة برقــم‬\n‫‪ 342150651‬وتاريــخ ‪1434/9/9‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلتــه املسـ ّـجل برقــم ‪ 34309203‬وتاريــخ ‪1434/8/29‬ه ـ اخلــاص‬\n‫بدعــوى ‪ ........‬ضــد‪ /‬بيــت املــال يف قضيــة حقوقيــة وقــد تضمــن الصــك‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة‬\n‫ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه‬\n‫إلــى ضــرورة تدويــن رقــم وتاريــخ برقيــة املقــام الســامي رقــم ‪ ........‬وتاريــخ‬\n‫‪1433/4/29‬ه ـ املرفقــة باملعاملــة املتضمنــة املوافقــة علــى نظــر دعــوى‬\n‫اإلعســار وذلــك يف الضبــط والصــك وســجله ؛ حيــث يلــزم ذلــك حســب‬\n‫التعليمــات يف إثبــات اإلعســار يف مواجهــة بيــت املــال ‪ ،‬فعلــى فضيلتــه‬\n‫إكمــال الــازم قبــل بعــث املعاملــة إلــى جهــة التنفيــذ ‪ ،‬ولبيانــه حــرر يف‬\n                                         ‫‪1434/9/13‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                                         ‫‪248‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":244,"source_page_end":248,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6c65fc860f042ebf76f5e48ab5fd4cbf4f1ba46b70c4f94b573e4cc71bc14208","normalized_text_hash":"113da7c478931f2fabb85e2f4eb2c0c29ad828b3a7fd2bd120f444735a17edfe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p244-34309203"},{"id":"06b35ec9-271c-5ac4-8642-c5b9e069857a","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -طلب إعسار بنفقة -صدور حكم بإلزام الولد (املدعي) بالنفقة على والده (املدعى عليه) -مطالبة املدعي إثبات اإلعسار- متسك املدعى عليه (الوالد) بالنفقة -عظم حق الوالد على ولده -صرف النظر عن الدعوى .","document_number":"34335085","case_number":"33463547","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/20","year":"1434","subject":"إعسار -طلب إعسار بنفقة -صدور حكم بإلزام الولد (املدعي) بالنفقة على والده (املدعى عليه) -مطالبة املدعي إثبات اإلعسار- متسك املدعى عليه (الوالد) بالنفقة -عظم حق الوالد على ولده -صرف النظر عن الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/10/20 :‬هـ‬\n                        ‫ُ‬                 ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪34335085 :‬‬\n                           ‫َر ْق ُم الدعوى‪33463547 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 35131603‬تاريخه‪1435/1/30 :‬هـ‬\n\n\n        ‫إعســار‪ -‬طلــب إعســار بنفقــة ‪ -‬صــدور حكــم بإلــزام الولــد (املدعــي)‬\n        ‫بالنفقــة علــى والــده (املدعــى عليــه)‪ -‬مطالبــة املدعــي إثبــات اإلعســار‪-‬‬\n        ‫متســك املدعــى عليــه (الوالــد) بالنفقــة‪ -‬عظــم حــق الوالــد علــى‬\n                                             ‫ولــده‪ -‬صــرف النظــر عــن الدعــوى ‪.‬‬\n\n\n\n\n                            ‫قوله صلى اهلل عليه وسلم (( أنت ومالك ألبيك )) ‪.‬‬\n\n\n\n\n        ‫ادعــى املدعــي ضــد والــده أنــه صــدر علــى املدعــي (االبــن) حكم ـ ًا‬\n        ‫بتســليم املدعــى عليــه (الوالــد) مبلغـ ًا وقدره خمســمائة ريال نفقة شــهرية‬\n        ‫وأنــه اســتمر يف الدفــع حتــى نهايــة شــهر ربيــع اآلخــر لعــام ‪1433‬ه ـ وأقــر‬\n        ‫املدعــي انــه تقاعــد وأصبــح دخلــه الشــهري تســعة آالف وثمامنائــة ريــال‬\n        ‫وأن لديــه زوجــة وخمســة أوالد أكبرهــم عمــره أربعــة وعشــرون ســنة‬\n        ‫وطلــب املدعــي إثبــات إعســاره واحلكــم علــى املدعــى عليــه بإنظــاره‬\n        ‫وإلــى حــن ميســرة‪ ،‬أجــاب املدعــى عليــه بــأن آخــر مــا ســلمه املدعــي‬\n        ‫هــو خمســمائة ريــال يف شــهر ربيــع اآلخــر لعــام ‪1432‬ه ـ وأنــه ال يســتطيع‬\n        ‫النفقــة علــى نفســه وعلــى مــن يعــول‪ ،‬مت مخاطبــة مؤسســة النقــد لإلفادة‬\n        ‫عــن أرصــدة طــريف القضيــة فــورد اجلــواب أن رصيــد املدعــى عليــه صفــر‬\n\n‫‪249‬‬\n\f‫وكشــف حســاب باإليداعــات لــه‪ ،‬طلــب املدعــي تخفيــض النفقــة إلــى‬\n‫ثالثمائــة ريــال‪ ،‬متــت مخاطبــة قســم اخلبــراء باحملكمــة لتقريــر نفقــة‬\n‫وفــق مــا قــرره الطرفــان مــع إدخــال بقيــة أوالد املدعــى عليــه القادريــن‬\n‫علــى النفقــة‪ ،‬طلــب املدعــى عليــه اســتمرار النفقــة املقــررة‪ ،‬قــرر ناظــر‬\n‫القضيــة إنــه لعظــم حــق الوالــد علــى ولــده ولقولــه صلــى اهلل عليــه وســلم‬\n‫(( أنــت ومالــك ألبيــك )) ولقلــة املبلــغ املتبقــي وقــدره مائتــا ريــال ممــا أقــر‬\n‫بــه املدعــي االســتعداد بتســليمه أخيــر ًا وقــدره ثالثمائــة ريــال فقــد صــدر‬\n‫احلكــم بصــرف النظــر عــن الدعــوى‪ ،‬مت إبــاغ املدعــى عليــه بصــورة‬\n‫مــن الصــك‪ ،‬صــدر قــرار محكمــة االســتئناف باملصادقــة علــى احلكــم‬\n                                                                           ‫باألكثريــة‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33463547‬وتاريــخ‬\n‫‪1433/07/13‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331196296‬وتاريــخ‬\n‫‪1433/06/25‬ه ـ حضــر ‪ ........‬ســجله ‪ ........‬وادعــى علــى احلاضــر معــه‬\n‫باملجلــس الشــرعي والــده‪ ........‬ســجله ‪ ........‬قائــا يف دعــواه عليــه ‪ :‬لقــد‬\n‫صــدر احلكــم مــن هــذه احملكمــة بــأن أدفــع لوالــدي املدعــى عليــه‬\n‫نفقــة شــهرية خمســمائة ريــال وذلــك مبوجــب الصــك الصــادر برقــم‬\n‫‪ 3/458/113‬يف ‪1421/7/18‬ه ـ وقــد اســتمريت يف الدفــع حتــى نهايــة‬\n‫شــهر ربيــع اآلخــر مــن هــذا العــام ‪1433‬ه ـ وحيــث إننــي لــم اعــد اســتطيع‬\n‫النفقــة بســبب تقاعــدي حيــث أصبــح دخلــي الشــهري تســعة اآلف‬\n\n                                                                                            ‫‪250‬‬\n\f      ‫وســتمائة ريــال ولــدي باإلضافــة إلــى الزوجــة خمســة أوالد أكبرهــم‬\n      ‫يبلــغ مــن العمــر أربــع وعشــرين ســنة لــذا أطلــب إثبــات إعســاري واحلكــم‬\n      ‫علــى املدعــى عليــه بإنظــاري إلــى ميســرة وبســؤال املدعــى عليــه قــال ‪ :‬إن‬\n      ‫آخــر مــا ســلم لــي املدعــي هــو خمســمائة ريــال يف شــهر ربيــع اآلخــر لعــام‬\n      ‫‪1432‬ه ـ وأنــا ال أســتطيع أن أنفــق علــى نفســي ومــن أعــول وعليــه تقــرر‬\n      ‫الكتابــة ملؤسســة النقــد العربــي الســعودي لإلفــادة عــن رصيــد كل مــن‬\n      ‫الطرفــن ورفعــت اجللســة ويف جلســة أخــرى حضــر املدعــي حــال حضــور‬\n      ‫والــده املدعــى عليــه حيــث قــرر املدعــي قائــا ‪ :‬إننــي ال أســتطيع النفقــة‬\n      ‫علــى والــدي باملبلــغ احملكــوم بــه يف الصــك املذكــور حيــث إننــي أعــول‬\n      ‫أســرتي الكبيــرة كمــا أن والــدي يســتلم ضمانــا اجتماعيــا باإلضافــة‬\n      ‫إلــى عــادة ســنوية مــن الديــوان امللكي مببلغ ثالثني ألــف ريال ‪ ،‬وبعرض‬\n      ‫على املدعى عليه قال ‪ :‬إنني اســتلم مبلغ الفني وخمســمائة ريال شــهريا‬\n      ‫كضمــان اجتماعــي حيــث إننــي أعــول زوجتــن أمــا مــا ذكــره ابنــي‬\n      ‫املدعــي مــن العــادة املذكــورة فقــد اســتلمتها مــرة واحــدة فقــط كمــا‬\n      ‫أننــي تعبــت مــن احلضــور لهــذه احملكمــة مــن ‪ .......‬حملافظــة الطائــف‬\n      ‫وال أســتطيع احلضــور لهــذه احملكمــة ‪ .‬هــذا وباالطــاع علــى أوراق‬\n      ‫املعاملــة ظهــر خطــاب مؤسســة النقــد العربــي الســعودي رقــم ‪33/261‬‬\n      ‫يف ‪1433/9/27‬ه ـ يتضمــن كشــف حســاب املدعــى عليــه والرصيــد‬\n      ‫صفــر ومرفــق بــه كشــف حســاب للمدعــى عليــه مــن ‪2010/12/7‬م‬\n      ‫الــى ‪2011/11/26‬م يتضمــن وجــود ايــداع مببلــغ ثالثــن ألــف ريــال يف‬\n      ‫‪2011/5/28‬م وايــداع يف ‪ 2011/9/19‬مببلــغ اربعــة وثالثــن ألــف ريــال‬\n      ‫اه ـ وعليــه تقــرر الكتابــة مــرة أخــري ملؤسســة النقد العربــي لإلفادة عن‬\n      ‫أرصــدة املدعــي وعليــه رفعــت لذلــك ويف جلســة أخــرى حضــر املدعــي‬\n\n\n‫‪251‬‬\n\f‫كمــا حضــر املدعــى عليــه حيــث قــرر املدعــي قائــا إننــي ال اســتطيع أن‬\n‫أنفــق علــى والــدي النفقــة الشــهرية خمســمائة ريــال وأطلــب تخفيضهــا‬\n‫الــى ثالثمائــة ريــال حســب اســتطاعتي وبعــرض ذلــك علــى املدعــى عليــه‬\n‫اننــي الزلــت أطلــب النفقــة التــي مت تقريرهــا مبوجــب احلكــم املذكــور‬\n‫ثــم ظهــر أنــه وردنــا خطــاب املؤسســة العامــة للتقاعــد يف ‪1434/2/4‬‬\n‫ه ـ يتضمــن أن مرتــب املدعــي تســعة آالف وســتمائة وثالثــون ريــاال أ‪.‬ه ـ‬\n‫وعليــه تقــرر احالــة املعاملــة لقســم اخلبــراء باحملكمــة لتقريــر النفقــة‬\n‫وفــق مــا ذكــره الطرفــان مــع ادخــال بقيــة أوالد املدعــى عليــه القادريــن‬\n‫علــى النفقــة ورفعــت اجللســة حلــن عــودة املعاملــة ويف جلســة أخــرى حضــر‬\n‫املدعــى عليــه ولــم يحضــر املدعــي وقــد عــادت إلينــا املعاملــة مــن قســم‬\n‫اإلصــاح باحملكمــة يتضمــن تســاهل املدعــي اهــ‪ .‬وبعــرض ذلــك علــى‬\n‫املدعــى عليــه قــرر قائــا إننــي الزلــت أطلــب اســتمرار النفقــة خمســمائة‬\n‫ريــال حيــث إن املدعــي قــادر علــى ذلــك فبنــاء الدعــوى ومــا أجــاب بــه‬\n‫املدعــى عليــه وحيــث أقــر املدعــي بقدرتــه علــى دفــع ثالثمائــة ريــال‬\n‫شــهريا ولقلــة املبلــغ املتبقــي مــن املبلــغ احملكــوم بــه ولعظــم حــق الوالــد‬\n‫علــى ولــده ولقولــه صلــى اهلل عليــه وســلم‪( :‬أنــت ومالــك ألبيــك) وبعــد‬\n‫اإلطــاع علــى الصــك احلكــم املشــار إليــه أعــاه لــذا حكمــت بصــرف‬\n‫النظــر عــن دعــوى املدعــي وأفهمــت املدعــى عليــه بأنــه ســيتم إبــاغ‬\n‫املدعــى عليــه بصــورة مــن صــك احلكــم إلبــداء اعتراضــه خــال ثالثــن‬\n‫يومــا مــن تاريــخ اســتالمه صــورة صــك احلكــم وأمــرت بتنظيــم صــك‬\n‫بذلــك وتســجيله وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/10/19‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n\n\n                                                                                        ‫‪252‬‬\n\f      ‫األولــى لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n      ‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n      ‫علــى املعاملــة الــواردة إلينــا شــفع خطــاب فضيلة رئيــس احملكمة العامة‬\n      ‫مبحافظــة جــدة رقــم ‪ 33/1196296‬وتاريــخ ‪1435/1/4‬ه ـ املشــتملة‬\n      ‫علــى الصــك رقــم ‪ 34335085‬وتاريــخ ‪1434/10/20‬ه ـ الصــادر مــن‬\n      ‫فضيلــة الشــيخ ‪ ........‬القاضــي باحملكمــة العامــة مبحافظــة جــدة‬\n      ‫املتضمــن دعــوى‪ ........‬ضــد‪ ........‬يف دعــوى إعســار عــن النفقــة وبدراســة‬\n      ‫الصــك وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى احلكــم واهلل‬\n               ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪253‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":249,"source_page_end":253,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d90560c4c10730decdd283f5ef4c422dd668c9042a618504fa09be545e55f434","normalized_text_hash":"d611488e61bd26926233af12f83929f09c11746dd089ac8f5b2a90a623fc27d7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p249-34335085"},{"id":"38981ef3-3da1-50f8-8892-de88bac09251","document_type":"judgment","category":"judicial","subcategory":"general","title":"براءة ذمة عن استهالك مدة سابقة من املياه -مطالبة شركة املياه بفصل مديونية املالك السابق للعقار عن احلالي -دفع الشركة بأن الدين متعلق بالعقار ال املالك -املنتفع احلقيقي لتلك اخلدمة هو املالك للعقار وقت تقدمي اخلدمة -إلزام الشركة مبحاسبة املدعى من وقت انتفاعه -رد دعوى الشركة بإلزام املدعي بدفع مديونية املالك السابق .","document_number":"33430561","case_number":"33361719","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/18","year":"1434","subject":"براءة ذمة عن استهالك مدة سابقة من املياه -مطالبة شركة املياه بفصل مديونية املالك السابق للعقار عن احلالي -دفع الشركة بأن الدين متعلق بالعقار ال املالك -املنتفع احلقيقي لتلك اخلدمة هو املالك للعقار وقت تقدمي اخلدمة -إلزام الشركة مبحاسبة املدعى من وقت انتفاعه -رد دعوى الشركة بإلزام املدعي بدفع مديونية املالك السابق .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/10/18 :‬هـ‬\n                        ‫ُ‬                 ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪33430561 :‬‬\n                           ‫َر ْق ُم الدعوى‪33361719 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                       ‫‪ 341681‬تاريخه‪1434/1/4:‬هـ‬\n\n\n       ‫بــراءة ذمــة عــن اســتهالك مــدة ســابقة مــن امليــاه ‪ -‬مطالبــة شــركة املياه‬\n       ‫بفصــل مديونيــة املالــك الســابق للعقــار عــن احلالــي ‪ -‬دفــع الشــركة‬\n       ‫بــأن الديــن متعلــق بالعقــار ال املالــك ‪ -‬املنتفــع احلقيقــي لتلــك‬\n       ‫اخلدمــة هــو املالــك للعقــار وقــت تقــدمي اخلدمــة ‪ -‬إلــزام الشــركة‬\n       ‫مبحاســبة املدعــى مــن وقــت انتفاعــه ‪ -‬رد دعــوى الشــركة بإلــزام‬\n                                    ‫املدعــي بدفــع مديونيــة املالــك الســابق ‪.‬‬\n\n\n\n\n                     ‫‪ -1‬قول اهلل تعالى «يا أيها الذين آمنوا أوفوا بالعقود»‪.‬‬\n       ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪« :‬املســلمون علــى شــروطهم» رواه‬\n                                                           ‫الترمــذي وأبــو داوود‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي بدعــوى ضــد شــركة (‪ ).....‬بأنــه اشــترى عقــار ًا فحملتــه‬\n       ‫املدعــى عليهــا مديونيــة ســابقة علــى مالــك العقار الســابق ويطلب فصلها‬\n       ‫عــن مديونيتــه ‪ -‬دفــع وكيــل الشــركة املدعــى عليهــا بــأن املديونيــة‬\n       ‫جتــري علــى العقــار ومتعلقــة بــه كالرهــن وال تعلــق لهــا يف ذمــة املالــك‬\n       ‫وأن علــى مشــتري العقــار اتخــاذ كافــة اإلجــراءات النظاميــة للبيــع مــن‬\n       ‫تصفيــة املســتحقات واملديونيــات وألن املشــتري لــم يفعــل ذلــك وعمــا‬\n\n‫‪263‬‬\n\f‫بالقاعدة «املفرط أولى باخلســارة» فإن مســؤولية ســداد املديونية متعلقة‬\n‫باملدعــي ولــه الرجــوع علــى البائــع ‪ ،‬وأقــر بــأن موكلتــه قطعــت املــاء عــن‬\n‫العــدادات حرصــا علــى عــدم تراكــم املديونيــة عليــه وطلــب رد دعــواه‬\n‫وإلزامــه بدفــع املبلــغ الــذي عليــه ‪ -‬جــرى االطــاع علــى صــك ملكيــة‬\n‫عقــار املدعــي ‪ -‬قــرر وكيــل املدعــى عليهــا بــأن اخلدمــة مفصولــة عــن‬\n‫العقــار قبــل شــراء املدعــي لــه ‪ -‬عليــه وألن اخلدمــة التــي تقدمهــا شــركة‬\n‫(‪ ).....‬تتعلــق مبالــك العقــار ال لذاتــه‪ ،‬واملنتفــع احلقيقــي لتلــك اخلدمــة هــو‬\n‫املالــك للعقــار وقــت تقــدمي اخلدمــة ‪ ،‬لــذا وبنــاء علــى مــا أقــر بــه املدعــى‬\n‫عليــه وكالــة مــن أن تاريــخ فصــل اخلدمــة كان قبــل شــراء املدعــي‬\n‫لذلــك العقــار‪ ،‬وألن حقيقــة اخلدمــة عقــد بــن املنتفــع ومقــدم اخلدمــة‬\n‫‪ ،‬وليــس العقــار طرفــا فيــه ‪ ،‬ولعــدم وجــود مقتضــى شــرعي أو نظامــي‬\n‫يلــزم املشــتري التحقــق مــن عــدم وجــود مديونيــة عليــه ‪ ،‬لــذا فــا يكــون‬\n‫املدعــي مفرطــا ‪ ،‬ولقولــه تعالــى «يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود»‪،‬‬\n‫وحلديــث «املســلمون علــى شــروطهم» رواه الترمــذي وأبــو داوود‪ ،‬لذلــك‬\n‫كلــه ‪ ،‬فقــد حكــم علــى املدعــى عليهــا ‪ ...‬مبحاســبة املدعــي منــذ‬\n‫تاريــخ متلكــه للعقــار وفصــل احلســاب القــدمي عــن حســابه اجلديــد ورد‬\n‫طلــب املدعــى عليهــا إلــزام املدعــي بدفــع املديونيــة املترتبــة علــى العقــار‬\n‫لفتــرة مــا قبــل متلــك املدعــي لــه ‪ -‬قــرر وكيــل املدعــى عليهــا االعتــراض‬\n         ‫فأفهــم بالتعليمــات ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                          ‫‪264‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33361719‬وتاريــخ‬\n      ‫‪1433/05/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33991086‬وتاريــخ‬\n      ‫‪1433/05/25‬ه ـ ففــي يــوم األربعــاء املوافق‪1433/08/14‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر (‪ ).....‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ ).....‬بصفتــه وكيــا عــن الســيد (‪ ).....‬ســعودي‬\n      ‫مبوجــب ســجل مدنــي رقــم (‪ ).....‬و(‪ ).....‬ســعودي مبوجــب ســجل مدنــي‬\n      ‫رقــم (‪ ).....‬و(‪ ).....‬ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬و(‪).....‬‬\n      ‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬و(‪ ).....‬ســعودي مبوجــب ســجل‬\n      ‫مدنــي رقــم (‪ ).....‬و(‪ ).....‬ســعودي مبوجــب ســجل مدني رقــم (‪ ).....‬و(‪).....‬‬\n      ‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬و(‪ ).....‬ســعودي مبوجــب ســجل‬\n      ‫مدنــي رقــم (‪ ).....‬و(‪ ).....‬ســعودي مبوجــب ســجل مدنــي رقــم (‪).....‬‬\n      ‫و(‪ ).....‬ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬بصفتهــم الشــخصية‬\n      ‫وبصفتهــم جميعـ ًا مــن ورثــه املتوفــى(‪ ).....‬مبوجــب صــك اإلرث رقــم ‪/65‬‬\n      ‫‪ 5‬يف ‪1428/3/19‬ه ـ املجلــد رقــم ‪ 5 /3‬الصــادر مــن احملكمــة العامــة‬\n      ‫مبحافظــة جــدة بعــد تعريفهــم الشــرعي مــن كل مــن ‪ ).....( :‬ســعودي‬\n      ‫مبوجــب ســجل مدنــي رقــم (‪ ).....‬و(‪ ).....‬ســعودي مبوجــب ســجل مدنــي‬\n      ‫رقــم (‪).....‬وادعــى علــى احلاضــر معــه (‪).....‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ ).....‬بصفتــه وكيــا عــن (‪).....‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬بصفتــه العضــو املنتــدب والرئيــس‬\n\n‫‪265‬‬\n\f‫التنفيــذي لشــركة (‪ ).....‬مبوجــب قــرار التعيــن رقــم ‪ 1/454‬وتاريــخ‬\n‫‪1429/5/30‬ه ـ ومبوجــب املــادة التاســعة عشــر مــن النظــام األساســي‬\n‫للشــركة الصــادر باملرســوم امللكــي رقــم م ‪ 1/‬وتاريــخ ‪1429/1/13‬ه ـ‬\n‫بالوكالة رقم ‪ 1019‬تاريخ ‪1431/8/8‬هـ جلد ‪ ، 79‬قائال‪ :‬أن موكلي‬\n‫قــد أشــترى العقــار الكائــن (‪ ).....‬مبوجــب الصــك الشــرعي الصــادر من‬\n‫كتابــة عــدل جــدة األولــى برقــم ‪ 572‬جلــد ‪/5‬ع بتاريــخ ‪1427/4/10‬ه ـ‬\n‫وفوجــئ موكلــي بعــد أن اســتلم العقــار أن املديريــة العامــة للميــاه‬\n‫مبنطقــة مكــة املكرمــة تطالبــه مببالــغ ضخمــة ومتأخــرات علــى‬\n‫عــدادات امليــاه التابعــة للعقــار وهــذا االســتهالك علــى املالــك الســابق‬\n‫وليــس علــى موكلــي وهــذا ثابــت لــدى املديريــة العامــة للميــاه مبنطقــة‬\n‫مكــة املكرمــة والعــدادات عليهــا مبالــغ متأخــرات قدميــة ال عالقــة‬\n‫ملوكلــي بهــا ‪ ،‬وقــد مت االنتقــال جميــع املســئوليات واألعمــال الفنيــة‬\n‫واإلداريــة واملاليــة اخلاصــة مبدينتــي الريــاض وجــدة واملوكلــة ملديرتــي‬\n‫امليــاه مبنطقتــي الريــاض ومكــة املكرمــة إلــى شــركة امليــاه الوطنيــة‬\n‫مبوجــب القــرار الــوزاري رقــم ‪ 1/954‬وتاريــخ ‪1429/10/16‬ه ـ ‪ ،‬أطلــب‬\n‫احلكــم بالــزام شــركة (‪ ).....‬مبحاســبة موكلــي منــذ تاريــخ متلكــه‬\n‫للعقــار يف ‪1427/4/10‬ه ـ وفصــل احلســاب القــدمي عــن حســابة اجلديــد‬\n‫واســتالم قيمــة االســتهالك التــي تخــص موكلــي ‪ .‬هــذه دعــواي ‪ .‬ثــم‬\n‫أبــرز املدعــي وكالــة صــورة صــك امللكيــة املشــار إليــه فوجدتــه يتضمن‬\n‫انتقــال ملكيــة الصــك للمدعــي يف ‪1427/4/10‬ه ـ جــرى االطــاع عليه‬\n‫وتزويــد أوراق املعاملــة بــه ‪ ،‬وبعرضــه علــى املدعــى عليــه وكالــة قــال ‪:‬‬\n‫أطلــب اإلمهــال للــرد ‪ .‬ثــم رفعــت اجللســة لذلــك ‪.‬ويف يــوم األربعــاء املوافــق‬\n‫‪1433/10/18‬هـ افتتحت اجللســة الســاعة ‪ 08 : 00‬وفيها حضر املدعي‬\n\n\n                                                                                        ‫‪266‬‬\n\f      ‫وكالــة ‪ ،‬وحضــر (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ ).....‬بصفتــه وكيــا عــن (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم (‪ ).....‬بصفتــه العضــو املنتــدب والرئيــس التنفيــذي لشــركة‬\n      ‫(‪ ).....‬مبوجــب قــرار التعيــن رقــم ‪ 1/454‬وتاريــخ ‪1429/5/30‬ه ـ‬\n      ‫ومبوجــب املــادة التاســعة عشــر مــن النظــام األساســي للشــركة الصــادر‬\n      ‫باملرســوم امللكــي رقــم م‪ 1/‬وتاريــخ ‪1429/1/13‬ه ـ والســجل التجــاري‬\n      ‫رقــم ‪ 1010247322‬وتاريــخ ‪1429/3/23‬ه ـ مبوجــب الوكالــة الصادرة‬\n      ‫مــن كاتــب العــدل املكلــف يف الهيئــة العامــة لالســتثمار برقــم ‪1018‬‬\n      ‫وتاريــخ ‪1431/8/8‬ه ـ جلــد ‪ ، 79‬وقــدم املدعــى عليــه وكالــة مذكــرة‬\n      ‫تتضمــن أن مــا ذكــره املدعــي وكالــة هــي مديونيــة ماليــة مترتبــة علــى‬\n      ‫اشــتراكات (‪ ).....‬التــي تغــذي العقــار الكائــن (‪ ، ).....‬واالشــتراكات‬\n      ‫هــي خلدمــة مرفــق العقــار وليســت للمالــك‪ ،‬فمســؤولية الســداد هــي‬\n      ‫علــى مالــك العقــار اجلديــد الــذي قبــل بالعقــار مبــا عليــه مــن مديونيــة‬\n      ‫‪ ،‬والديــن املتعلــق بالعقــار يــدور معــه وجــودا وعدمــا ‪ ،‬كالرهــن علــى‬\n      ‫عقــار ‪ ،‬فإنــه يظــل معلقــا بالعقــار ‪ ،‬وكان علــى مشــتري العقــار اتخــاذ‬\n      ‫كافــة اإلجــراءات النظاميــة للبيــع مــن تصفيــة املســتحقات واملديونيــات‬\n      ‫‪ ،‬واملدعــي وكالــة لــم يفعــل ذلــك ‪ ،‬وعمــا بالقاعــدة (املفــرط أولــى‬\n      ‫باخلســارة) فــإن مســؤولية ســداد املديونيــة متعلقــة باملدعــي كــون العقــار‬\n      ‫حتــت يــده وتصرفــه ‪ ،‬ومــن ثــم للمدعــي الرجــوع علــى البائــع ‪ ،‬وقــد‬\n      ‫مت قطــع امليــاه عــن العــدادات حرصــا علــى عــدم تراكــم املبلــغ بصــورة‬\n      ‫أكبــر ‪ ،‬وعليــه فنلتمــس مــن فضيلتكــم رد دعــوى املدعــي ملــا ذكــر‬\n      ‫أعــاه ‪ ،‬وإلــزام املدعــي بســداد املديونيــة املســتحقة علــى اشــتراكات‬\n      ‫امليــاه التــي تغــذي العقــار املشــار إليــه دون مماطلــة ‪ .‬وبعــرض ذلــك علــى‬\n\n\n‫‪267‬‬\n\f‫املدعــي وكالــة قــال ‪ :‬ليــس لــدي جديــد ‪ ،‬بــل الصحيــح أن مــا ينطبــق‬\n‫علينــا هــو قولــه تعالــى (وال تــزر وازرة وزر أخــرى) كمــا أن املنفعــة ملالــك‬\n‫العقــار وليســت للعقــار ذاتــه ‪ .‬وبســؤال املدعــى عليــه وكالــة متــى كان‬\n‫تاريــخ فصــل امليــاه قــال ‪ :‬هــو قبــل شــراء املدعــي للعقــار ‪ .‬فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة ‪ ،‬ومبــا أن اخلدمــة التــي تقدمهــا شــركة‬\n‫(‪ ).....‬هــي خدمــة تتعلــق مبالــك العقــار وليســت لــذات العقــار ‪ ،‬واملنتفــع‬\n‫احلقيقــي لتلــك اخلدمــة هــو املالــك للعقــار وقــت تقــدمي اخلدمــة ‪ ،‬وبنــاء‬\n‫علــى مــا أقــر بــه املدعــى عليــه وكالــة مــن أن تاريــخ فصــل اخلدمــة كان‬\n‫قبــل شــراء املدعــي لذلــك العقــار ‪،‬ومبــا أن تلــك اخلدمــة هــي يف حقيقتهــا‬\n‫عقــد بــن املنتفــع ومقــدم اخلدمــة ‪ ،‬وليــس العقــار طرفــا فيــه ‪ ،‬وبنــاء‬\n‫علــى الصــك الصــادر مــن كتابــة عــدل جــدة األولــى برقــم ‪ 572‬جلــد‬\n‫‪/5‬ع وتاريــخ ‪1427/4/10‬ه ـ ‪ ،‬ومبــا أن األنظمــة والعــرف ال يلزمــان‬\n‫املشــتري لعقــار التحقــق منعــدم وجــود مديونيــة عليــه ‪ ،‬فــا يكــون‬\n‫املدعــي مفرطــا ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود) ‪،‬‬\n‫وحلديــث (املســلمون علــى شــروطهم) رواه الترمــذي وأبــو داوود ‪،‬لذلــك‬\n‫كلــه ‪ ،‬فقــد ألزمــت املدعــى عليهــا شــركة (‪ ).....‬مبحاســبة املدعــي‬\n‫(‪ ).....‬منــذ تاريــخ متلكــه للعقــار يف ‪1427/4/10‬ه ـ وفصــل احلســاب‬\n‫القــدمي عــن حســابه اجلديــد كونــه املنتفــع باخلدمــة منــذ تاريــخ متلكــه‬\n‫للعقــار ‪ ،‬ورددت دعــوى املدعــى عليهــا إلــزام املدعــي بدفــع املديونيــة‬\n‫املترتبــة علــى العقــار للفتــرة مــا قبــل متلــك املدعــي لــه ‪ .‬وبــه حكمــت ‪ .‬وبــه‬\n‫قنــع املدعــي وكالــة ‪ ،‬وقــرر املدعــى عليــه االعتــراض‪ ،‬وجــرى تســليمه‬\n‫نســخة مــن احلكــم وإفهامــه بــأن لــه احلــق يف االعتــراض عليــه خــال‬\n‫ثالثــن يومــا ‪ ،‬وإال ســقط حقــه يف االعتــراض ‪ ،‬واكتســب احلكــم‬\n\n\n                                                                                            ‫‪268‬‬\n\f      ‫القطعيــة ‪ .‬وأقفلــت اجللســة الســاعة (‪ )9:40‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/10/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي باحملكمــة العامة بجدة‬\n      ‫خلــف الشــيخ (‪ ).....‬ففــي يــوم االثنــن املوافــق ‪1434/1/19‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 8 : 15‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بخطــاب رئيســها رقــم ‪ 33227636‬وتاريــخ ‪1434/1/11‬ه ـ وبالقــرار‬\n      ‫رقــم ‪ 341681‬وتاريــخ ‪1434/1/4‬ه ـ واملتضمــن مــا يلــي وبدراســة‬\n      ‫احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى‬\n      ‫احلكــم وحتــى ال يخفــى جــرى أثباتــه وأمــرت بأحلاقــه بصكــه وســجله‬\n      ‫وأقفلــت اجللســة الســاعة ‪ 8 : 32‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n             ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/1/19‬ه ـ ‪.‬‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ فق ــد ج ــرى‬\n      ‫م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n      ‫الصــادر مــن فضيلــة الشــيخ (‪ ).....‬القاضــي باحملكمــة العامــة مبحافظــة‬\n      ‫جــدة واملســجل بع ــدد ‪ 33430561‬وتاريــخ ‪1433/10/18‬ه ـ املتضمــن‬\n      ‫دعــوى الســيد (‪ ).....‬ضــد شــركة (‪ ،).....‬احملكــوم في ــه مبــا دون‬\n      ‫باطنــه ‪ ،‬وبدراس ــة احلكــم وص ــورة ضبط ــه و الئحتــه االعتراضيــة تق ــرر‬\n      ‫باألكثريــة املوافق ــة عل ــى احلكــم ‪ ،‬واهلل املوفــق وصل ــى اهلل عل ــى نبينــا‬\n                                                 ‫محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪269‬‬\n\f270\n\f271\n\f272\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":263,"source_page_end":272,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6a06498f6c90f785218e02ed21d1d63fa7790eedcb023de364f112cd4d4d691e","normalized_text_hash":"ed5b1e9abdeeed8a0cfc98bacd1a365b7cb169f3544dedd2915c108dcf0cc0b5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p263-33430561"},{"id":"22440ba9-dacc-5f3a-a821-785d816ee77f","document_type":"judgment","category":"judicial","subcategory":"general","title":"والية -طلب أم فسخ والية أخ ألخيه -الوالية ثابته لأخ بوصية األب -احلكم برد الدعوى.","document_number":"34176193","case_number":"32229211","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/1","year":"1434","subject":"والية -طلب أم فسخ والية أخ ألخيه -الوالية ثابته لأخ بوصية األب -احلكم برد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/4/1 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34176193 :‬‬\n                         ‫َر ْق ُم الدعوى‪32229211 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34242013‬تاريخه‪1434/6/14:‬هـ‬\n\n\n\n      ‫واليــة ‪ -‬طلــب أم فســخ واليــة أخ ألخيــه ‪ -‬الواليــة ثابتــه لــأخ بوصيــة‬\n                                                   ‫األب ‪ -‬احلكــم بــرد الدعــوى‪.‬‬\n\n\n\n\n      ‫قــال يف شــرح املنتهــى (ثــم (الواليــة بعــد أب) لوصيــة ألنــه نائــب األب‬\n                                               ‫أشــبه وكيلــه يف احليــاة)‪.175/2‬‬\n\n\n\n\n      ‫أقامــت أم دعــوى علــى ابــن زوجهــا تطالبــه بفســخ واليتــه عــن أخيــه‬\n      ‫الــذي هــو ابــن املدعيــة وجعلهــا للمدعيــة ألنهــا األحــق بالواليــة ‪ -‬صــادق‬\n      ‫املدعــى عليــه علــى انــه الولــي علــى أخيــه غيــر الشــقيق وقــرر أنــه ال مانــع‬\n      ‫لديــه مــن إقامــة املدعيــة وليــة علــى ابنهــا بشــروط ‪ -1‬ان ال تســافر بــه‬\n      ‫خــارج البــاد ‪ -2‬أال تشــحذ بــه ‪ -3‬أن تســمح للمدعــى عليــه بأخــذه‬\n      ‫كل خميــس لرؤيــة إخوتــه عرضــت احملكمــة الشــروط علــى املدعيــة‬\n      ‫فرفضــت بحجــة أنهــا ال عالقــة لهــا بالواليــة ‪ -‬حاولــت احملكمــة الصلــح‬\n      ‫بــن الطرفــن فرفضــت املدعيــة فطلبــت منهــا احملكمــة البينــة علــى‬\n      ‫صالحيتهــا للواليــة فلــم حتضــر أحــدا وقــرر املدعــى عليــه أن والــده‬\n      ‫أوصــاه قبــل وفاتــه بــأن يكــون وصيــا علــى إخوانــه القاصريــن ورفــض‬\n      ‫فســخ الواليــة عنــه ثــم أبــرز للمحكمــة دفتــر كتــب فيــه وصيــة جعــل‬\n\n‫‪273‬‬\n\f‫فيهــا املدعــى عليــه وصيــا علــى أخيــه املذكــور وقــرر املدعــى عليــه أن‬\n‫هــذا هــو خــط والــده وبعــرض الوصيــة علــى املدعيــة ذكــرت أنهــا ال علــم‬\n‫لهــا بــه وال تعــرف خــط زوجهــا وحتــى لــو كان خطــه فهــي مصــرة علــى‬\n‫طلــب إقامتهــا وليــة علــى ابنهــا ‪ -‬طلبــت احملكمــة مــن املدعــى عليــه‬\n‫البينــة علــى أن تلــك الوصيــة كانــت بخــط والــده فأحضــر شــاهدين‬\n‫شــهدا بــأن اخلــط املذكــور هــو خــط والــد املدعــى عليــه وجــرى تعديــل‬\n‫الشــهود ‪ -‬ثــم ادعــت املدعيــة أن املدعــى عليــه ال ينفــق علــى أخيــه‬\n‫القاصــر فأنكــر املدعــى عليــه وأبــرز تســعة وعشــرين كشــف حتويــل‬\n‫مببالــغ ماليــة لصالــح القاصــر وأقــرت املدعيــة بذلــك وادعــت أن هــذا‬\n‫ال يكفــي ‪ -‬وبنــاء علــى الوصيــة ومــا أبــرزه املدعــى عليــه مــن احلــواالت‬\n‫الشــهرية لصالــح القاصــر وألن األحــق بالواليــة وصــي األب ألنــه نائــب‬\n‫عنــه لــذا ردت احملكمــة دعــوى املدعيــة ‪ -‬اعترضــت املدعيــة ‪ -‬صــدق‬\n                                           ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫برقــم وتاريــخ ‪1432/06/14‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ‬\n‫‪1432/6/14‬ه ـ ففــي يــوم األحــد املوافق‪1432/07/10‬ه ـ حضــرت‬\n‫(‪ ).....‬ســعودية مبوجــب ســجل مدنــي رقــم (‪ ).....‬مطابقــة بطاقتهــا‬\n‫مــن قبــل مفتشــة النســاء يف احملكمــة حســب اإلفــادة املرفقــة مبلــف‬\n‫الدعــوى‪ .‬ولــم يحضــر املدعــى عليــه وأفــادت املدعيــة أنهــا ســلمت ورقــة‬\n‫التبليــغ إلــى أخيــه ‪ .‬ويف يــوم الثالثــاء املوافــق ‪1432/10/22‬ه ـ حضــرت‬\n\n                                                                                   ‫‪274‬‬\n\f      ‫املدعيــة املــدون هويتهــا ســابق ًا وادعــت علــى احلاضــر معهــا (‪ ).....‬ســعودي‬\n      ‫مبوجــب ســجل مدنــي رقــم (‪ ).....‬قائلــة يف دعواهــا‪ :‬املدعــى عليــه هــذا‬\n      ‫احلاضــر أخ ألب البنــي املولــود بتاريــخ ‪1423/2/2‬ه ـ وقــد تولــى علــى‬\n      ‫ابنــي املذكــور مبوجــب الصــك الصــادر مــن ســلفكم برقــم وتاريــخ‬\n      ‫‪1423/6/3‬ه ـ وذلــك بــدون موافقتــي ومبــا أننــي أحــق بالواليــة علــى ابني‬\n      ‫لــذا أطلــب فســخ واليــة املدعــى عليــه وإقامتــي وليــه علــى ابنــي املذكــور‬\n      ‫هــذه دعــواي ‪ .‬وبعرضهــا علــى املدعــى عليــه أجــاب قائــا ‪ :‬مــا ذكرتــه‬\n      ‫املدعيــة أننــي ولــي علــى ابنهــا أخــي غيــر الشــقيق مبوجــب الصــك املشــار‬\n      ‫إليــه فصحيــح وكان هــذا مبوافقتهــا يف حينــه وأمــا طلبهــا فســخ واليتــي‬\n      ‫علــى أخــي املذكــور وإقامتهــا وليــة عليــه فــا مانــع لــدي بشــروط أو ًال‬\n      ‫‪ :‬أن ال تســافر بــه خــارج البــاد ‪ .‬ثاني ـ ًا ‪ :‬أن ال تشــحذ بــه‪ .‬ثالث ـ ًا ‪ :‬أن‬\n      ‫تســمح لــي بأخــذه كل خميــس لرؤيــة أخوتــي‪ .‬هكــذا أجــاب‪ .‬وبعــرض‬\n      ‫ذلــك علــى املدعيــة أجابــت قائلــة ‪ :‬أرفــض تلــك الشــروط ألنهــا ليــس لهــا‬\n      ‫عالقــة بالواليــة ولــم اشــحذ بــه وإمنــا ذهبــت إلــى اجلمعيــات اخليريــة لطلــب‬\n      ‫املســاعدة ألنــي أرملــة وهــو يتيــم وأمــا الشــرط الثالــث فأنــا ال أرفــض أن‬\n      ‫يأخــذه للزيــارة وإمنــا (‪ ).....‬نفســه هــو مــن يرفــض وأمــا مــا ذكــره أن تلــك‬\n      ‫صــك الواليــة كان مبوافقتــي فغيــر صحيــح هكــذا أجابــت‪ .‬وجــرى‬\n      ‫عــرض الصلــح بــن الطرفــن فرفضــت املدعيــة لــذا أفهمــت املدعيــة أن‬\n      ‫عليهــا البينــة علــى صالحيتهــا للواليــة علــى ابنهــا فاســتعدت بإحضارهــا‬\n      ‫يف جلســة قادمــة‪ .‬ويف يــوم األربعــاء املوافــق ‪1433/2/17‬ه ـ حضــرت‬\n      ‫املدعيــة واملدعــى عليــه املــدون هويتهمــا ســابق ًا وبســؤال املدعيــة عــن‬\n      ‫بينتهــا علــى صالحيتهــا للواليــة أجابــت قائلــة‪ :‬لــم أحضــر بينــة هكــذا‬\n      ‫أجابــت‪ .‬وقــرر املدعــى عليــه قائــا‪ :‬لقــد أوصــى والــدي قبــل وفاتــه بــأن‬\n\n\n‫‪275‬‬\n\f‫أكــون وصيــا علــى إخوانــي وبالــذات القاصريــن منهــم ولهــذا أرفــض‬\n‫فســخ واليتــي علــى أخــي هكــذا أجــاب ثــم أبــرز دفتــر وكتــب فيــه‬\n‫وصيــة وهــذا نــص احلاجــة منهــا‪ :‬بســم اهلل الرحمــن الرحيــم إن احلمــد هلل‬\n‫نحمده ونســتعينه ونســتهديه ونعوذ باهلل من شــرور أنفســنا ومن ســيئات‬\n‫أعمالنــا مــن يهــده اهلل فــا مضــل لــه ومــن يضلــل فــا هــادي لــه وأشــهد‬\n‫أال إلــه إال اهلل وحــده ال شــريك لــه وأشــهد أن محمــدا عبــده ورســوله أدى‬\n‫األمانــة ونصــح األمــة صلــى اهلل عليــه وعلــى الــه وصحبــه وســلم وأشــهد‬\n‫أن اجلنــة حــق وأن النــار حــق وأن اهلل يبعــث مــن يف القبــور وبعــد‪ :‬يكــون‬\n‫ابنــي وصيــا علــى إخوانــه وبالــذات القاصريــن منهــم والبنــات إلــى اخــره‬\n‫واملنتهــي باســم املوصــي وتوقيعــه يف ‪1411/4/18‬ه ـ أهــ‪ .‬وقــرر املدعــى‬\n‫عليــه قائــا‪ :‬وهــذا هــو خــط والــدي هكــذا قــرر‪ .‬وبعــرض ذلــك علــى‬\n‫املدعيــة أجابــت قائلــة‪ :‬لــم أعلــم بتلــك الوصيــة ولــم يخبرنــي بهــا والده وال‬\n‫أدري إن كان هــذا خطــه أم ال وحتــى لــو كان هــذا خطــه فأنــا مصــرة‬\n‫علــى طلبــي إقامتــي وليــة علــى ابنــي هكــذا أجابــت‪ .‬وبســؤال املدعــى‬\n‫عليــه عــن بينتــه علــى أن تلــك الوصيــة كانــت بخــط والــده أجــاب قائــا‪:‬‬\n‫نعــم لــدي بينــة وأطلــب مهلــة إلحضارهــا هكــذا أجــاب‪ .‬ويف يــوم الســبت‬\n‫املوافــق ‪1433/12/18‬ه ـ حضــرت املدعيــة ولــم يحضــر املدعــى عليــه‬\n‫وأفــادت املدعيــة أنهــا اســتلمت ورقــة التبليــغ وأبلغــت املدعــى عليــه‬\n‫وبســؤالها عمــا يثبــت لــم تبــرز شــيئا لــذا أفهمتهــا أنــه ال بــد مــن أخــذ‬\n    ‫توقيعــه علــى ورقــة التبليــغ أو إبالغــه عــن طريــق محضــري اخلصــوم‪.‬‬\n‫ويف يــوم األربعــاء املوافق‪1434/02/06‬ه ـ حضــرت املدعيــة وحضــر‬\n‫املدعــى عليــه وحضــر ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬مــن‬\n‫مواليــد ‪1387/8/18‬ه ـ وأفــاد أنــه يســكن يف مدينــة ويعمل يف وعالقته‬\n\n\n                                                                                        ‫‪276‬‬\n\f      ‫باملدعــى عليــه ابــن خالــه وجــرى اطالعــه علــى الوصيــة املكتوبــة‬\n      ‫املنســوبة للمتوفــى املــدون نصهــا يف اجللســة الثالثــة فشــهد قائــا‪ :‬أشــهد‬\n      ‫أن خــط هــذه الوصيــة هــو خــط خالــي هكــذا شــهد كمــا حضــر (‪).....‬‬\n      ‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬مــن مواليــد ‪1387/7/1‬ه ـ‬\n      ‫وأفــاد أنــه يســكن يف (‪ ).....‬ويعمــل يف (‪ ).....‬وعالقتــه باملدعــى عليــه‬\n      ‫أنــه ابــن عمــه الشــقيق وجــرى اطالعــه علــى الوصيــة املكتوبــة املنســوبة‬\n      ‫للمتوفــى املــدون نصهــا يف اجللســة الثالثــة فشــهد قائــا‪ :‬أشــهد أن خــط‬\n      ‫هــذه الوصيــة هــو خــط عمــي هكــذا شــهد وبعــرض الشــاهدين علــى‬\n      ‫املدعيــة أجابــت قائلــة‪ :‬أمــا الشــاهد األول فــا اعرفــه وكذلــك الشــاهد‬\n      ‫الثانــي ال اعرفــه ومــا ذكــر يف الشــهادة فــا أدري عنــه ألنــي ال أعــرف‬\n      ‫خــط مورثنــا هكــذا أجابــت وأفهمــت املدعــى عليــه بإحضــار مزكــن‬\n      ‫للشــاهدين فاســتعد بذلــك ‪ .‬ويف يــوم األحــد املوافــق ‪1434/03/29‬ه ـ‬\n      ‫حضــرت املدعيــة (‪ ).....‬وحضــر املدعــى عليــه وقــررت املدعيــة قائلــة لنــا‪:‬‬\n      ‫أنــا ال أرغــب يف أن تســتمر يف نظــر القضيــة وســوف أطلــب مــن الرئيــس‬\n      ‫تغييــرك ثــم خرجــت مــن مجلــس القضــاء بحضــور (‪ ).....‬وشــهادة كاتبــه‬\n      ‫املــازم القضائــي لدينــا‪ .‬وأحضــر املدعــى عليــه (‪ ).....‬ســعودي مبوجــب‬\n      ‫ســجل مدنــي رقــم (‪ ).....‬و(‪ ).....‬مصــري مبوجــب رخصــة إقامــة رقــم‬\n      ‫(‪ ).....‬وشــهد كل واحــد منهمــا منفــردا بقولــه‪ :‬أشــهد بعدالــة وتزكيــة‬\n      ‫وهكــذا شــهدا‪ .‬ويف هــذه األثنــاء حضــرت املدعيــة وجلســت يف مجلــس‬\n      ‫القضــاء وبســؤالها هــل لديهــا مــا تضيفــه علــى الدعــوى أجابــت قائلــة‪:‬‬\n      ‫نعــم أنــا أرفــض احلكــم لــه بالواليــة ألنــه ال ينفــق عليــه هكــذا أجابــت‪.‬‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا‪ :‬بــل أنفــق عليــه شــهريا‬\n      ‫مبوجــب حتويــل علــى حســابها علــى مصــرف (‪ ).....‬ثــم أبــرز تســعة‬\n\n\n‫‪277‬‬\n\f‫وعشــرين كشــف حتويــل مببالــغ ماليــة مــا بــن ألــف ومائتــن ريــال وألف‬\n‫ريــال وبعــرض ذلــك علــى املدعيــة أجابــت قائلــة‪ :‬هــذا صحيــح ولكنــه‬\n‫نصيــب ابنــي مــن تقاعــد والــده ولكــن هــذه ال تكفــي وأنــا أريــد الواليــة‬\n‫حتــى أســجل ابنــي يف اجلمعيــات اخليريــة كمــا أنــه كان يســلم لــي يف‬\n‫أول األمــر ســتمائة ريــال فقــط ملــدة ســتة ســنوات وملــا راجعــت مصلحــة‬\n‫التقاعــد تبــن لــي أن نصيــب ابنــي مــن تقاعــد والــده يبلــغ تســعمائة‬\n‫وخمســن ريــاال هكــذا أجابــت‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n‫قائــا‪ :‬مــا ذكرتــه أنــي كنــت أســلم لهــا ســتمائة ريــال فغيــر صحيــح‬\n‫وأوراق التحويــات التــي أبرزتهــا لكــم تثبــت خالفــه وقــد أقــرت بهــا‬\n‫وليــس لــدي مانــع أن أزيــد هــذا التحويــل مــن جيبــي اخلــاص بــل وأدفــع لــه‬\n‫أجــرة الســكن ولكــن بشــرط أن تســكن مــع والدهــا حتــى يحفظهــا‬\n              ‫ويحفــظ الولــد وليــس أن تســكن مبفردهــا هكــذا أجــاب‪.‬‬\n‫قــال يف شــرح منتهــى اإلرادات (‪« : )175/2‬واليــة ( صغيــر ) عاقــل أو‬\n‫مجنــون ( وبالــغ مجنــون ) ومــن بلــغ ســفيها واســتمر (ألب بالــغ ) لكمــال‬\n‫شــفقته ‪ ،‬فــإن أحلــق الولــد بابــن عشــر فأكثــر ولــم يثبــت بلوغــه فــا‬\n‫واليــة لــه ‪ -‬ألنــه لــم ينفــك عنــه احلجــر فــا يكــون وليــا ( رشــيد ) ‪ -‬ألنــه‬\n‫غيــر محجــور عليــه ثــم ) الواليــة بعــد أب ) لوصيــه ألنــه نائــب األب ‪،‬‬\n‫أشــبه وكيلــه يف احليــاة «فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫والوصيــة التــي أبرزهــا املدعــى عليــه والبينــة علــى كونــت لــك الوصيــة‬\n‫بخــط والــده ومــا أبــرزه مــن حــوالت شــهرية للمدعيــة وقــد أقــرت بهــا‬\n‫ودفعــت أنهــا ال تكفــي» لــذا فقــد قــررت رد دعــوى املدعيــة وبه حكمت‬\n‫وبإعــان احلكــم قــررت احملكــوم عليهــا املعارضــة وطلبــت االســتئناف‬\n‫وأفهمــت باملراجعــة يف يــوم األحــد املوافــق ‪1434/4/7‬ه ـ الســتالم صورة‬\n\n\n                                                                                         ‫‪278‬‬\n\f      ‫احلكــم وتقــدمي الئحــة االعتــراض خــال ثالثــن يومـ ًا فــإن مضــت املــدة‬\n      ‫ولــم تقــدم الئحــة اعتراضهــا ســقط حــق االعتــراض واكتســب احلكــم‬\n      ‫القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/29‬ه ـ‬\n      ‫ويف يــوم األربعــاء ‪1434/07/05‬ه ـ افتتحــت اجللســة بنــاء علــى‬\n      ‫ورود املعاملــة بشــرح رئيــس احملكمــة علــى القيــد رقــم وتاريــخ‬\n      ‫‪1434/06/26‬ه ـ وبرفقهــا خطــاب رئيــس محكمــة االســتئناف رقــم‬\n      ‫وتاريــخ ‪1434/06/24‬ه ـ وبرفقهــا قــرار دائــرة األحــوال الشــخصية‬\n      ‫األولــى رقــم وتاريــخ ‪1434/06/14‬ه ـ واملتضمــن املصادقــة علــى احلكــم‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                  ‫وســلم‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتمييــز‬\n      ‫قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة برقــم وتاريــخ‬\n      ‫‪1434/5/27‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم وتاريخ‪1434/4/1‬ه ـ اخلــاص‬\n      ‫بدعــوى(‪ ).....‬ضــد(‪ ).....‬بشــأن واليــة وقــد تضمــن الصــك أن فضيلتــه رد‬\n      ‫دعــوى املدعيــة وبــه حكــم ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض‪ .‬واهلل‬\n                   ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪279‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":273,"source_page_end":279,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"303d12b5d017adfdaec545635f7a616bf61f3401d4eeaa8f85463be3f51e4e2c","normalized_text_hash":"9c8e337198bcf05c60ea4faf1dcc57dce3a1572779f59ba5cb3a7809aefe9162","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p273-34176193"},{"id":"9f275531-f7b4-51ca-8b0e-0d4a31e53163","document_type":"judgment","category":"judicial","subcategory":"general","title":"والية -نزع والية التزويج من األب الغائب -شهادة الشهود العدول بغيبة األب -احلكم بإسقاط والية األب يف التزويج وجعلها لأخ احلاضر -رفع احلكم حملكمة الاستئناف كون احلكم على غائب.","document_number":"34196443","case_number":"33667978","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/23","year":"1434","subject":"والية -نزع والية التزويج من األب الغائب -شهادة الشهود العدول بغيبة األب -احلكم بإسقاط والية األب يف التزويج وجعلها لأخ احلاضر -رفع احلكم حملكمة الاستئناف كون احلكم على غائب.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/23 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34196443 :‬‬\n                   ‫َر ْق ُم الدعوى‪33667978 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34215208‬تاريخه‪1434/5/18 :‬هـ‬\n\n\n‫واليــة ‪ -‬نــزع واليــة التزويــج مــن األب الغائــب ‪ -‬شــهادة الشــهود العــدول‬\n‫بغيبــة األب ‪ -‬احلكــم بإســقاط واليــة األب يف التزويــج وجعلهــا لــأخ‬\n‫احلاضــر ‪ -‬رفــع احلكــم حملكمــة االســتئناف كــون احلكــم علــى غائــب‪.‬‬\n\n\n\n‫‪ .1‬جــاء يف املغنــي ‪( 386/9‬وقــد قــال أحمــد يف موضــع إذا كان األب‬\n                                                    ‫بعيــد الســفر يــزوج األخ)‪.‬‬\n‫‪ .2‬قال ابن قدامة رحمه اهلل يف مســألة ســفر الولي ســفرا بعيدا ‪386/9‬‬\n‫(وهــذا القــول إن شــاء اهلل تعالــى أقربهــا إلــى الصــواب فــإن التحديــدات‬\n‫بابهــا التوقيــف وال توقيــف يف هــذه املســألة فتــرد إلــى مــا يتعارفه الناس‬\n‫بينهــم ممــا لــم جتــر العــادة باالنتظــار فيــه ويلحــق املــرأة الضــرر مبنعهــا‬\n‫مــن التزويــج يف مثلــه فإنــه يتعــذر يف ذلــك الوصــول إلــى املصلحــة مــن‬\n‫نظــر األقــرب فيكــون كاملعــدوم والتحديــد بالعــام كبيــر فــإن الضــرر‬\n                       ‫يلحــق باالنتظــار يف مثــل ذلــك ويذهــب اخلاطــب)‪.‬‬\n\n\n\n‫ادعــت املدعيــة علــى أبيهــا الغائــب تطالــب بإســقاط واليــة التزويــج عنــه‬\n‫لغيبتــه وجعلهــا ألخيهــا ‪ -‬حيــث تقــدم لهــا خطــاب وكان املانــع مــن‬\n‫إجــراء عقــد النــكاح هــو عــدم وجــود الولــي فقــد ســافر منــذ أكثــر‬\n‫مــن تســعة أشــهر وال يعلــم عنــه شــيء ‪ -‬وردت إفــادة الشــرطة أن املدعــى‬\n                                                                                        ‫‪280‬‬\n\f      ‫عليــه ســافر بتاريــخ ‪1433/8/20‬ه ـ كمــا وردت اجابــة شــئون املوظفــن‬\n      ‫مــن ان املذكــور قــد اســتقال مــن العمــل بتاريــخ ‪1431/3/30‬ه ـ ‪ -‬أبــدى‬\n      ‫أخوهــا الشــقيق موافقتــه علــى تولــي عقــد النــكاح وتزويــج أختــه ‪-‬‬\n      ‫أحضــرت املدعيــة شــهود ًا يشــهدون بغيبــة األب وعــدم رجوعــه مــن ســفره‬\n      ‫وأن أخاهــا الشــقيق أهــل لواليــة التزويــج ‪ -‬ملــا نــص عليــه اإلمــام أحمــد‬\n      ‫مــن أن األب إذا كان بعيــد الســفر يــزوج األخ (املغنــي ‪ - )386/9‬وحيــث‬\n      ‫إن املدعــى عليــه قــد ســافر ســفرا بعيــدا ولــم يتواصــل مــع أوالده طيلــة‬\n      ‫الفتــرة املمتــدة لتســعة أشــهر‪ -‬وحيــث إن املدعيــة متضــررة مــن عــدم‬\n      ‫وجــود ولــي لهــا يتولــى تزويجهــا ‪ -‬وحيــث حضــر أخــو املدعيــة وأبــدى‬\n      ‫موافقتــه علــى تولــي واليــة النــكاح ألختــه املدعيــة ‪ -‬صــدر احلكــم‬\n      ‫بنــزع واليــة النــكاح مــن املدعــى عليــه يف تزويــج املدعيــة وجعلــت واليــة‬\n      ‫التزويــج ألخيهــا ‪-‬قــررت املدعيــة القناعــة ورفــع احلكــم حملكمــة‬\n      ‫االســتئناف كــون احلكــم علــى غائــب ‪ -‬صــدق احلكــم مــن دائــرة‬\n               ‫األحــوال الشــخصية الثانيــة مبحكمــة االســتئناف بالريــاض ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.........‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 33667978‬وتاريــخ ‪ 1433/11/21‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 332077950‬وتاريــخ ‪ 1433/11/21‬ه ـ ففــي‬\n      ‫يوم الثالثاء املوافق‪ 1434/04/23‬هـ افتتحت اجللســة الســاعة ‪11 : 30‬‬\n      ‫وفيهــا حضــرت املدعيــة ‪ .........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n      ‫رقــم ‪ .........‬واملعــرف بهــا مــن قبــل أخيهــا ‪ .........‬ســعودي اجلنســية مبوجــب‬\n\n‫‪281‬‬\n\f‫الهويــة الوطنيــة ‪.........‬وادعــت قائلــة إن أبي قد غادر اململكة منذ أكثر‬\n‫مــن تســعة أشــهر وال نعلــم عنــه أي شــيء ســوى أنــه ذهــب للمغــرب ولــم‬\n‫يقــم باالتصــال بنــا وقــد تقــدم لــي خطــاب وكان املانــع من عقــد النكاح‬\n‫هــو عــدم وجــود الولــي أطلــب إســقاط واليــة التزويــج عــن أبــي وإعطائهــا‬\n‫أخــي الشــقيق األكبــر ‪...‬هــذه دعــواي وبطلــب البينــة مــن املدعيــة‬\n‫أجابــت بينتــي مــا يف أوراق القضيــة وشــهود هكــذا اجابــت وكان قــد‬\n‫جــرت الكتابــة ألمــارة منطقــة الريــاض للبحــث عــن املدعــى عليــه وذلــك‬\n‫بخطابــي رقــم ‪ 33/2089346‬وتاريــخ ‪1433/11/23‬ه ـ فورد اجلواب من‬\n‫مركــز شــرطة املعــذر رقــم ‪ 6/229/2‬وتاريــخ ‪1434/1/14‬ه ـ املتضمــن‬\n‫أنــه بعــد االستفســار عــن املذكــور اتضــح أنــه خــارج البــاد مــن تاريــخ‬\n‫‪1433/8/20‬ه ـ إلــى دولــة املغــرب الشــقيقة مبوجــب البرنــت املرفــق أ‪.‬ه ـ‬\n‫كمــا جــرى الكتابــة لعمــل املدعــى عليــه لــدى هيئــة الطيــران املدنــي‬\n‫وذلــك بخطابــي رقــم ‪ 3320891‬وتاريــخ ‪1433/11/23‬ه ـ فــورد اجلــواب‬\n‫مــن مديــر عــام شــؤون املوظفــن برقــم ‪ 19458/1/32/256‬وتاريــخ‬\n‫‪1433/12/26‬ه ـ املتضمــن أنــه بعــد البحــث يف ســجالت املوظفــن‬\n‫تبــن أن املذكــور قــد اســتقال مــن العمــل بتاريــخ ‪1431/3/30‬ه ـ مرفــق‬\n‫صــورة مــن قــرار االســتقالة أ‪.‬ه ـ كمــا جــرى ســؤال أخ املدعيــة ‪...‬املــدون‬\n‫هويتــه أعــاه عــن موافقتــه يف تولــي نــكاح وتزويــج أختــه فأجــاب‬\n‫باملوافقــة وبطلــب الشــهود أحضــرت املدعيــة كال مــن ‪ .........‬ســعودي‬\n‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪.........‬و‪.........‬ســعودي اجلنســية‬\n‫مبوجــب الهويــة الوطنيــة رقــم ‪.........‬وشــهدا كل واحــد منهمــا منفــردا‬\n‫قائــا أشــهد أن والــد املدعيــة ‪ .........‬قــد غــادر اململكــة ولــم يرجــع منــذ‬\n‫تســعة أشــهر وأن أخــو املدعيــة ‪...‬هــذا احلاضــر هــو األخ الشــقيق للمدعيــة‬\n\n\n                                                                                       ‫‪282‬‬\n\f      ‫وأهــل لواليــة التزويــج هكــذا شــهدا وبطلــب مزكــن للشــهود أحضــرت‬\n      ‫‪.........‬و‪.........‬وشــهدا بعدالــة وثقــة الشــاهدين أعــاه فبنــاء علــى مــا ســبق‬\n      ‫مــن الدعــوى ومــا أحضرتــه املدعيــة مــن البينــة املعدلــة شــرعا ومــا جــاء‬\n      ‫يف خطــاب شــرطة املعــذر مــن خــروج املدعــى عليــه اململكــة مــن تاريــخ‬\n      ‫‪1433/8/20‬ه ـ ولــم يرجــع ومــا جــاء يف خطــاب عمــل املدعــى عليــه وملــا‬\n      ‫نــص عليــه اإلمــام أحمــد مــن أن األب إذا كان بعيــد الســفر يــزوج األخ‬\n      ‫(املغنــي ‪ )386/9‬وحيــث أن املدعــى عليــه قــد ســافر ســفرا بعيــدا ولــم‬\n      ‫يتواصــل مــع أوالده طيلــة الفتــرة املمتــدة لتســعة أشــهر قــال ابــن قدامــه‬\n      ‫رحمــه اهلل يف مســألة ســفر الولــي ســفرا بعيــدا ( وهــذا القــول إن شــاء‬\n      ‫اهلل تعالــي أقربهــا إلــى الصــواب فــإن التحديــدات بابهــا التوقيــف وال‬\n      ‫توقيــف يف هــذه املســألة فتــرد إلــى مــا يتعارفــه النــاس بينهــم ممــا لــم جتــر‬\n      ‫العــادة باالنتظــار فيــه ويلحــق املــرأة الضــرر مبنعهــا مــن التزويــج يف مثلــه‬\n      ‫فإنــه يتعــذر يف ذلــك الوصــول إلــى املصلحــة مــن نظــر األقــرب فيكــون‬\n      ‫كاملعــدوم والتحديــد بالعــام كبيــر فــإن الضــرر يلحــق باالنتظــار يف‬\n      ‫مثــل ذلــك ويذهــب اخلاطــب )املغنــي ‪ 386/9‬وحيــث أن املدعيــة متضــررة‬\n      ‫مــن عــدم وجــود ولــي لهــا يتولــى تزويجهــا وحيــث حضــر أخــو املدعيــة‬\n      ‫‪...‬املرصــود أعــاه هويتــه وأبــدى موافقتــه علــى تولــي واليــة النــكاح‬\n      ‫ألختــه املدعيــة لــذا فقــد نزعــت واليــة النــكاح مــن املدعــى عليــه يف‬\n      ‫تزويــج املدعيــة وجعلــت واليــة التزويــج ألخيهــا احلاضــر ‪...‬وبــه حكمــت‬\n      ‫وقــررت املدعيــة القناعــة وســيجري احلكــم حملكمــة االســتئناف كــون‬\n      ‫احلكــم علــى غائــب واختتمــت اجللســة الســاعة ‪ 12،10‬وبــاهلل التوفيــق‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                          ‫‪1434/04/23‬هـ‬\n\n\n‫‪283‬‬\n\f‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض املســجل برقــم ‪ 332077950‬وتاريــخ ‪1434/5/4‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪........./‬‬\n‫املســجل برقــم‪ 34196443‬وتاريــخ ‪1434/4/23‬ه ـ اخلــاص بدعــوى‪/‬‬\n‫‪.........‬ضــد‪ /‬والدهــا‪ .‬بشــأن طلــب إســقاط واليــة التزويــج عنــه لغيبتــه‬\n‫وإعطائهــا لشــقيقها ‪.........‬وقــد تضمــن الصــك حكــم فضيلتــه مباهــو‬\n‫مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n‫تقــرر الدائــرة باألكثريــة املصادقــة علــى احلكــم ‪ -‬واهلل املوفــق وصلــى‬\n                        ‫اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪284‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":280,"source_page_end":284,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"422c02166a4fe302c754d02dcd92ca77eea2a64d5f41972035d84babce17cbfe","normalized_text_hash":"c367cedfd2ef35212fb5aaa3356a19b6f9b682f98cfb02f0796d85e7def47c9e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p280-34196443"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
